UPDATE services SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Создание сайтов","short":"Одностраничный сайт, сайт компании или интернет-магазин — одинаково удобный на телефоне и компьютере.","description":"Создаём сайт для вашей компании, услуг или товаров. Согласуем с вами страницы, дизайн и нужные функции и запускаем сайт.","features":["Структура страниц и план текстов","Дизайн без шаблонов — под ваш бренд","Адаптация под телефон, планшет и компьютер","Форма заявки — уведомление сразу приходит в Telegram","Кнопки телефона, Telegram и карты","Работаем над быстрой загрузкой сайта","Базовое SEO: заголовки и описания, sitemap, Google Search Console и Яндекс Вебмастер","Google Analytics и Яндекс Метрика","Подключение домена, хостинга и SSL (https)","Проверка на разных телефонах и в браузерах перед запуском"],"$h":{"name":"hikg5z","short":"zd0cdu","description":"18y3yr5","features":"n66jwq"}},"en":{"name":"Website development","short":"A one-page site, a company website or an online store — equally convenient on phone and desktop.","description":"We build a website for your company, services or products. We agree on the pages, design and features with you and launch the site.","features":["Page structure and content plan","Custom design that fits your brand — no templates","Responsive layout for phone, tablet and desktop","Contact form — requests arrive in Telegram instantly","Phone, Telegram and map buttons","We work on fast page loading","Basic SEO: titles and descriptions, sitemap, Google Search Console and Yandex Webmaster","Google Analytics and Yandex Metrica","Domain, hosting and SSL (https) setup","Testing on different phones and browsers before launch"],"$h":{"name":"hikg5z","short":"zd0cdu","description":"18y3yr5","features":"n66jwq"}}}'),
