  '$.examples[3].i18n', json('{"ru":{"name":"Корпоративный сайт Uzum","owner":"Uzum · Узбекистан","text":"Сайт экосистемы, объединяющий на одной странице Market, Tezkor, Bank, Nasiya и другие сервисы.","image":"/media/public/83a20354-89ac-426d-9c9e-87ca420828b7.webp","$h":{"name":"l2p77v","owner":"2ir9n5","text":"fa6n0n"}},"en":{"name":"Uzum corporate website","owner":"Uzum · Uzbekistan","text":"An ecosystem site that brings Market, Tezkor, Bank, Nasiya and other services together on one page.","image":"/media/public/ef5e65eb-cbbd-44cb-b24c-bd6da077b85f.webp","$h":{"name":"l2p77v","owner":"2ir9n5","text":"fa6n0n"}}}'))
