UPDATE services SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Telegram-боты и приложения","short":"Бот, который принимает заказы, или полноценное приложение внутри Telegram (Mini App).","description":"Создаём бота для приёма заказов, записи клиентов или ответов на вопросы. Если нужны каталог и корзина, делаем приложение, которое открывается прямо в Telegram.","features":["Сценарий бота: меню, кнопки и шаги","Узбекский и русский языки","Приём заказов, заявок или записи на приём","Уведомления о новых заказах вам и сотрудникам","Массовая рассылка пользователям","Статистика пользователей и заказов","Установка на сервер и контроль бесперебойной работы"],"$h":{"name":"ze64mm","short":"18qo7h","description":"191bn5d","features":"39psqa"}},"en":{"name":"Telegram bots and apps","short":"A bot that takes orders, or a full app that opens inside Telegram (Mini App).","description":"We build bots that take orders, book appointments or answer questions. If you need a catalog and a cart, we build an app that opens right inside Telegram.","features":["Bot flow: menus, buttons and steps","Uzbek and Russian languages","Accepting orders, requests or appointment bookings","New-order alerts for you and your staff","Broadcast messages to users","User and order statistics","Server deployment and uptime monitoring"],"$h":{"name":"ze64mm","short":"18qo7h","description":"191bn5d","features":"39psqa"}}}'),
