  '$.examples[3].i18n', json('{"ru":{"name":"Oshme","owner":"Oshme · Узбекистан","text":"Бот-путеводитель по ресторанам, кафе и барам: поиск места и бронирование столика.","imageMobile":"/media/public/e273d319-11be-4c8e-8820-8438d4294885.webp","$h":{"name":"1jhb76n","owner":"xbxviq","text":"yh8qyb"}},"en":{"name":"Oshme","owner":"Oshme · Uzbekistan","text":"A guide bot for restaurants, cafes and bars: find a place and book a table.","imageMobile":"/media/public/bafc3c0b-c7e5-4732-bb6c-a7370202f47f.webp","$h":{"name":"1jhb76n","owner":"xbxviq","text":"yh8qyb"}}}'),
  '$.examples[4].i18n', json('{"ru":{"name":"Цветов.ру Mini App","owner":"Цветов.ру · Россия","text":"Цветочный магазин внутри Telegram: букет можно выбрать из более чем 300 магазинов в 212 городах и заказать без регистрации.","image":"/media/public/7b40bd6e-88be-44c4-8405-354ee020701e.webp","imageMobile":"/media/public/ca300191-7bfb-4bbb-b485-4d8ef02685be.webp","$h":{"name":"16gjtjv","owner":"1t5w9ta","text":"1mip8n8"}},"en":{"name":"Tsvetov.ru Mini App","owner":"Tsvetov.ru · Russia","text":"A flower shop inside Telegram: choose a bouquet from over 300 shops in 212 cities and order without signing up.","image":"/media/public/7f443d44-fce1-4411-8a5b-aebf8551d9cb.webp","imageMobile":"/media/public/7565f614-6943-4c2f-82f9-5c6707d8b632.webp","$h":{"name":"16gjtjv","owner":"1t5w9ta","text":"1mip8n8"}}}'),
