UPDATE services SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Программы и приложения для бизнеса","short":"Веб-программа, CRM (система управления клиентами и заказами) или мобильное приложение.","description":"Создаём программу для управления клиентами, заказами, задачами и отчётами. В зависимости от задачи делаем веб-программу или мобильное приложение.","features":["Изучение рабочих процессов и план системы","До разработки вы прощёлкиваете макет","Пользователи, роли и права доступа","База клиентов, заказов и задач","Отчёты и графики","Уведомления через Telegram","Перенос данных из Excel","Рабочая версия на каждом этапе","Регулярное резервное копирование и защищённый вход","Установка на сервер"],"$h":{"name":"1kv8x77","short":"e2x14s","description":"dcamfk","features":"11356s7"}},"en":{"name":"Business software and apps","short":"Browser-based software, a CRM (a system for managing customers and orders) or a mobile app.","description":"We build software to manage customers, orders, tasks and reports. Depending on your work, it can be a browser-based system or a mobile app.","features":["Workflow research and system plan","Click through a prototype before development","Users, roles and permissions","Database of customers, orders and tasks","Reports and charts","Telegram notifications","Migration of your Excel data","A working version at every stage","Regular backups and secure sign-in","Server deployment"],"$h":{"name":"1kv8x77","short":"e2x14s","description":"dcamfk","features":"11356s7"}}}'),
