  '$.examples[3].i18n', json('{"ru":{"name":"Uzum Nasiya","owner":"Uzum · Узбекистан","text":"Приложение рассрочки: просмотр лимита, покупки и оплата через Payme, Click и Uzum Bank.","imageMobile":"/media/public/3a37da94-814a-460f-adad-d5cafa0f6d6a.webp","$h":{"name":"1t4u163","owner":"2ir9n5","text":"4hsv9l"}},"en":{"name":"Uzum Nasiya","owner":"Uzum · Uzbekistan","text":"An installment app: check your limit, shop and pay via Payme, Click and Uzum Bank.","imageMobile":"/media/public/6e7c8299-00dc-4e63-8330-50ddb7de75dc.webp","$h":{"name":"1t4u163","owner":"2ir9n5","text":"4hsv9l"}}}'),
  '$.examples[4].i18n', json('{"ru":{"name":"BILLZ","owner":"BILLZ · Узбекистан","text":"Программа для магазинов: товары, клиенты, продажи, касса и финансы в одном месте. Ей пользуются более 7 000 магазинов.","image":"/media/public/d58ab7e3-48ff-43fa-a1d1-02ccd4d495ce.webp","imageMobile":"/media/public/751a555f-6773-4eb5-b6f9-fda20087c0b2.webp","$h":{"name":"1xa1esy","owner":"1n5df7z","text":"193tvq0"}},"en":{"name":"BILLZ","owner":"BILLZ · Uzbekistan","text":"Software for retail stores: products, customers, sales, checkout and finances in one place. Used by more than 7,000 stores.","image":"/media/public/fe12e3b9-1595-4c2c-9a8d-0111f069c9f3.webp","imageMobile":"/media/public/2f6ccd21-768b-4596-b035-30f4d1730d7a.webp","$h":{"name":"1xa1esy","owner":"1n5df7z","text":"193tvq0"}}}'))
