UPDATE services SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Создание AI-ассистента","short":"Ассистент, который сам отвечает на вопросы, собирает заявки и при необходимости передаёт их сотруднику.","description":"Создаём ассистента, который отвечает на вопросы клиентов на основе предоставленных вами данных. Он принимает заявки и передаёт нужные вопросы сотруднику.","features":["База знаний: ваши цены, услуги, вопросы и ответы, документы","Ответы на узбекском (латиница и кириллица) и русском","Сохранение обращения и контактов клиента","Передача сложного вопроса сотруднику","Уведомление о новой заявке в Telegram","Редактирование ответов в админ-панели","История диалогов и статистика","Настройка ответов в течение первого месяца","Оплата AI-сервиса (токены) — отдельно, ежемесячный расход рассчитаем заранее"],"$h":{"name":"qpfcdg","short":"zoth5j","description":"16ltfct","features":"19cn3ir"}},"en":{"name":"AI assistant development","short":"An assistant that answers questions on its own, collects leads and hands off to a staff member when needed.","description":"We build an assistant that answers customer questions based on the information you provide. It takes requests and forwards the right questions to your staff.","features":["Knowledge base: your prices, services, FAQs and documents","Answers in Uzbek (Latin and Cyrillic) and Russian","Saves each request and the customer’s contact details","Hands complex questions to a staff member","Telegram alert for every new lead","Edit answers in the admin panel","Conversation history and statistics","Fine-tuning of answers during the first month","AI service (token) costs are billed separately — we estimate the monthly spend upfront"],"$h":{"name":"qpfcdg","short":"zoth5j","description":"16ltfct","features":"19cn3ir"}}}'),
