  '$.packages[1].i18n', json('{"ru":{"name":"Ассистент для заказов и интеграций","features":["Несколько каналов: Telegram, сайт, Instagram","Приём заказов и ссылка на оплату","Подключение к CRM или 1C","Понимание голосовых сообщений"],"fit":"Нужен ассистент, который работает с заказами, оплатой и CRM","$h":{"name":"1fxmnbe","features":"1y86ybw","fit":"1s0gq0m"}},"en":{"name":"Orders and integrations assistant","features":["Several channels: Telegram, website, Instagram","Order taking and payment links","CRM or 1C integration","Understands voice messages"],"fit":"I need an assistant that handles orders, payments and CRM","$h":{"name":"1fxmnbe","features":"1y86ybw","fit":"1s0gq0m"}}}'),
  '$.examples[0].i18n', json('{"ru":{"name":"Lola — ассистент банка","owner":"TBC Bank · Узбекистан","text":"AI-ассистент в приложении на узбекском и русском: отвечает на вопросы и при необходимости соединяет с оператором.","imageMobile":"/media/public/65e969ed-b04e-4b38-9b70-db269515e831.webp","$h":{"name":"6d79tl","owner":"1x69nez","text":"1i6act5"}},"en":{"name":"Lola — a banking assistant","owner":"TBC Bank · Uzbekistan","text":"An in-app AI assistant in Uzbek and Russian: it answers questions and connects you to an operator when needed.","imageMobile":"/media/public/34420234-873d-4b1f-8021-eb67858c86c0.webp","$h":{"name":"6d79tl","owner":"1x69nez","text":"1i6act5"}}}'),
  '$.examples[1].i18n', json('{"ru":{"name":"AI-ассистент Kaspi","owner":"Kaspi.kz · Казахстан","text":"По данным компании, сам отвечает на большую часть переписок и звонков клиентов, а Kasper даёт советы во время покупки.","imageMobile":"/media/public/0c2854d3-7173-457d-980a-96b4ec19900a.webp","$h":{"name":"5ocwzz","owner":"md3x9s","text":"1jy2d52"}},"en":{"name":"Kaspi AI assistant","owner":"Kaspi.kz · Kazakhstan","text":"According to the company, it handles most customer chats and calls on its own, while Kasper gives advice during purchases.","imageMobile":"/media/public/0775c6f1-15f1-43f7-80c6-5a1fa4f3195a.webp","$h":{"name":"5ocwzz","owner":"md3x9s","text":"1jy2d52"}}}'),
  '$.examples[2].i18n', json('{"ru":{"name":"AI-ассистент Klarna","owner":"Klarna · Швеция","text":"Бот поддержки на более чем 35 языках: по данным компании, решает большую часть обращений без участия оператора.","image":"/media/public/7d85142b-3f1f-4677-b4f6-5ecf17d62f75.webp","imageMobile":"/media/public/c1e69bf2-339a-4550-8e1d-bb186993ec20.webp","$h":{"name":"hzeups","owner":"16c8jkt","text":"yvy77r"}},"en":{"name":"Klarna AI assistant","owner":"Klarna · Sweden","text":"A support bot that works in more than 35 languages: according to the company, it resolves most requests without an operator.","image":"/media/public/0da611c6-a72b-4703-b21b-91aa981ffa8b.webp","imageMobile":"/media/public/3af3674d-0f65-4a45-afad-e10053f13ee3.webp","$h":{"name":"hzeups","owner":"16c8jkt","text":"yvy77r"}}}'),
  '$.examples[3].i18n', json('{"ru":{"name":"Чат-боты Uzum Avto","owner":"Uzum · Узбекистан","text":"На большинство первичных обращений в Telegram отвечает бот, остальные он передаёт оператору.","imageMobile":"/media/public/a2bd0c17-ad92-4fff-a8ed-26ee2e247351.webp","$h":{"name":"1bauq4y","owner":"2ir9n5","text":"5admgu"}},"en":{"name":"Uzum Avto chatbots","owner":"Uzum · Uzbekistan","text":"A bot answers most first-line requests on Telegram and routes the rest to an operator.","imageMobile":"/media/public/ebcd3528-b49c-4d62-9d5a-a573cfa276fa.webp","$h":{"name":"1bauq4y","owner":"2ir9n5","text":"5admgu"}}}'))
