UPDATE services SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Подключение оплаты и других систем","short":"Подключаем ваш сайт, бот или приложение к Payme, Click, CRM (системе управления клиентами и заказами), 1C и SMS-сервисам.","description":"Подключаем к вашему сайту, боту или приложению оплату, SMS и другие сервисы. Связываем данные о заказах и товарах с вашей учётной системой.","features":["Оплата: Payme, Click, Uzum, карты Uzcard и Humo","CRM: amoCRM, Bitrix24","Учёт и склад: 1C, МойСклад, Billz","SMS: Eskiz, Playmobile","Уведомления в Telegram и Google Sheets","Помощь с открытием мерчанта в платёжной системе","Сначала проверка в тестовом режиме, затем боевое подключение","Статусы оплаты и заказа обновляются автоматически"],"$h":{"name":"1rwhkni","short":"mhmaa2","description":"6rm8cm","features":"18qr0p4"}},"en":{"name":"Payment and system integrations","short":"We connect your website, bot or app to Payme, Click, CRM (customer and order management) systems, 1C and SMS services.","description":"We connect payments, SMS and other services to your website, bot or app, and link order and product data with your accounting system.","features":["Payments: Payme, Click, Uzum, Uzcard and Humo cards","CRM: amoCRM, Bitrix24","Accounting and inventory: 1C, MoySklad, Billz","SMS: Eskiz, Playmobile","Telegram notifications and Google Sheets","Help opening a merchant account with a payment provider","Testing in sandbox mode first, then going live","Payment and order statuses update automatically"],"$h":{"name":"1rwhkni","short":"mhmaa2","description":"6rm8cm","features":"18qr0p4"}}}'),
  '$.packages[0].i18n', json('{"ru":{"name":"Подключение платёжных систем","features":["Payme, Click, Uzum","Карты Uzcard и Humo","Статус оплаты автоматически записывается в заказ"],"fit":"Хочу принимать оплату на сайте или в боте","$h":{"name":"qdj19c","features":"fmul6l","fit":"35rve7"}},"en":{"name":"Payment integration","features":["Payme, Click, Uzum","Uzcard and Humo cards","Payment status is written to the order automatically"],"fit":"I want to accept payments on my website or bot","$h":{"name":"qdj19c","features":"fmul6l","fit":"35rve7"}}}'),
  '$.packages[1].i18n', json('{"ru":{"name":"Заявки в CRM","features":["amoCRM или Bitrix24","Заявки с сайта, бота и форм"],"fit":"Чтобы заявки сами попадали в CRM","$h":{"name":"1bs8zay","features":"1rlywum","fit":"86ziki"}},"en":{"name":"Leads to CRM","features":["amoCRM or Bitrix24","Leads from your website, bot and forms"],"fit":"I want leads to land in my CRM automatically","$h":{"name":"1bs8zay","features":"1rlywum","fit":"86ziki"}}}'),
  '$.packages[2].i18n', json('{"ru":{"name":"SMS и уведомления","features":["Eskiz или Playmobile","SMS с кодом подтверждения и статусом заказа","Уведомления в Telegram"],"fit":"Хочу отправлять клиентам SMS","$h":{"name":"1xow66l","features":"1efjmfa","fit":"yfu78i"}},"en":{"name":"SMS and notifications","features":["Eskiz or Playmobile","SMS with verification codes and order status","Telegram notifications"],"fit":"I want to send SMS to customers","$h":{"name":"1xow66l","features":"1efjmfa","fit":"yfu78i"}}}'),
  '$.packages[3].i18n', json('{"ru":{"name":"Подключение учёта и склада","features":["1C, МойСклад или Billz","Обмен товарами, остатками и ценами"],"fit":"Нужно связать с 1C или складом","$h":{"name":"1tb768p","features":"4esj18","fit":"hw7zkw"}},"en":{"name":"Accounting and inventory integration","features":["1C, MoySklad or Billz","Sync of products, stock and prices"],"fit":"I need to connect 1C or my inventory","$h":{"name":"1tb768p","features":"4esj18","fit":"hw7zkw"}}}'),
  '$.examples[0].i18n', json('{"ru":{"name":"Telegram + Bitrix24","owner":"Uzum Avto · Узбекистан","text":"Переписка в Telegram подключена к CRM (системе работы с клиентами): обращения автоматически попадают к нужному сотруднику.","image":"/media/public/e40be0a7-63c1-4076-a80c-8489d6e55e40.webp","$h":{"name":"wimk91","owner":"41d8hn","text":"1ba14t4"}},"en":{"name":"Telegram + Bitrix24","owner":"Uzum Avto · Uzbekistan","text":"Telegram chats are connected to a CRM (customer management system): requests are routed to the right staff member automatically.","image":"/media/public/f10e4677-6cbc-400c-af20-960fc054f316.webp","$h":{"name":"wimk91","owner":"41d8hn","text":"1ba14t4"}}}'),
  '$.examples[1].i18n', json('{"ru":{"name":"Платёжные системы в магазине","owner":"Texnomart · Узбекистан","text":"На сайте подключены оплата через Uzcard, Humo, Payme и Click, а также рассрочка.","image":"/media/public/a271cb54-0c3e-473e-bf32-1993396a3f91.webp","imageMobile":"/media/public/2cade303-3ae5-4315-b4d7-a19ccd46a348.webp","$h":{"name":"ngvxa","owner":"100r4m8","text":"1rp6zz7"}},"en":{"name":"Payments in an online store","owner":"Texnomart · Uzbekistan","text":"The site accepts Uzcard, Humo, Payme and Click, plus installment payments.","image":"/media/public/6cac9d86-a620-487c-8e99-222743f1c707.webp","imageMobile":"/media/public/10e7c602-ae9e-4b8d-b4f0-f193102ddd9d.webp","$h":{"name":"ngvxa","owner":"100r4m8","text":"1rp6zz7"}}}'),
  '$.examples[2].i18n', json('{"ru":{"name":"Платёжные системы в приложении","owner":"Uzum Nasiya · Узбекистан","text":"В приложении можно оплатить через Payme, Click, Uzum Bank и Paynet.","imageMobile":"/media/public/5d0b7353-5011-48d5-93d5-2111275f4409.webp","$h":{"name":"ecny72","owner":"7xnm5q","text":"12lsen2"}},"en":{"name":"Payments in an app","owner":"Uzum Nasiya · Uzbekistan","text":"The app accepts payments via Payme, Click, Uzum Bank and Paynet.","imageMobile":"/media/public/934c5551-daee-4bd7-9918-df307f41d0a7.webp","$h":{"name":"ecny72","owner":"7xnm5q","text":"12lsen2"}}}'),
  '$.examples[3].i18n', json('{"ru":{"name":"Eskiz SMS","owner":"Eskiz · Узбекистан","text":"SMS-сервис: отправляет коды подтверждения и уведомления с сайта, из бота или CRM через API.","image":"/media/public/eeb49091-09a8-40f5-a457-59a118234e0a.webp","imageMobile":"/media/public/d93853b6-c5c9-46df-abb2-8ea97fb8797d.webp","$h":{"name":"1nttui0","owner":"15e2b5s","text":"12ppn5y"}},"en":{"name":"Eskiz SMS","owner":"Eskiz · Uzbekistan","text":"An SMS service that sends verification codes and notifications from a website, bot or CRM via API.","image":"/media/public/38a2d937-2452-42ec-a9fe-b2849822770f.webp","imageMobile":"/media/public/e59a1051-0947-403e-9d7b-bbfc0d9ae82d.webp","$h":{"name":"1nttui0","owner":"15e2b5s","text":"12ppn5y"}}}'),
  '$.examples[4].i18n', json('{"ru":{"name":"UzumSync — МойСклад и Uzum Market","owner":"SellerMind · приложение для МойСклад","text":"Само передаёт остатки из МойСклад в Uzum Market и каждые 5 минут загружает заказы FBS и DBS в МойСклад.","image":"/media/public/8961f67c-f42b-425f-8413-58628d62a290.webp","$h":{"name":"4latxg","owner":"16kb4px","text":"1vkh5ay"}},"en":{"name":"UzumSync — MoySklad and Uzum Market","owner":"SellerMind · MoySklad app","text":"Pushes stock levels from MoySklad to Uzum Market and pulls FBS and DBS orders into MoySklad every 5 minutes.","image":"/media/public/32b4b1f1-adc1-4546-b4be-99c4c2a49221.webp","$h":{"name":"4latxg","owner":"16kb4px","text":"1vkh5ay"}}}'))
