UPDATE services SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Продвижение сайта в Google и Яндексе","short":"Аудит, настройка и ежемесячная работа, чтобы ваш сайт был выше в Google и Яндексе.","description":"Проверяем сайт для поисковых систем, исправляем технические ошибки и дорабатываем тексты страниц. Отчитываемся о проделанной работе и переходах из поиска.","features":["Анализ ключевых слов на узбекском и русском и конкурентов","Технический аудит: скорость, индексация, sitemap, robots.txt, мобильная версия","Оптимизация заголовков, описаний и текстов","Блоки вопросов и ответов и структурированные данные (schema)","Google Search Console и Яндекс Вебмастер","Google Бизнес Профиль, Яндекс Бизнес и 2GIS","Отчёт: что сделано и какой результат"],"$h":{"name":"19uu5vl","short":"tdc49v","description":"d1m0yj","features":"1pd5o2y"}},"en":{"name":"Search optimization for Google and Yandex","short":"An audit, setup and monthly work to help your website rank higher on Google and Yandex.","description":"We check your website for search engines, fix technical issues and optimize page content. We report on the work done and on traffic from search.","features":["Uzbek and Russian keyword and competitor research","Technical audit: speed, indexing, sitemap, robots.txt, mobile view","Optimization of titles, descriptions and copy","FAQ blocks and structured data (schema)","Google Search Console and Yandex Webmaster","Google Business Profile, Yandex Business and 2GIS","Report: what was done and what it achieved"],"$h":{"name":"19uu5vl","short":"tdc49v","description":"d1m0yj","features":"1pd5o2y"}}}'),
