UPDATE services SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Техническая поддержка сайтов и ботов","short":"Ежемесячное обслуживание, чтобы ваш сайт или бот всегда работал, был защищён и обновлён.","description":"Следим за работой сайта или бота, делаем резервные копии и устраняем неисправности. В рамках согласованного объёма обновляем тексты, фото и цены.","features":["Мониторинг работы сайта или бота","Регулярное резервное копирование","Обновления безопасности и защита","Исправление ошибок","Обновление текстов, фото и цен","Контроль сроков домена, хостинга и SSL","Проверка скорости","Берём и сайты с ботами, сделанные другими"],"$h":{"name":"401yen","short":"wvgfhq","description":"1wddnlg","features":"1gwfb2v"}},"en":{"name":"Website and bot maintenance","short":"A monthly service that keeps your website or bot running, secure and up to date.","description":"We monitor your website or bot, make backups and fix problems. Within the agreed scope, we also update text, images and prices.","features":["Website or bot uptime monitoring","Regular backups","Security updates and protection","Bug fixes","Updates to text, images and prices","Tracking domain, hosting and SSL renewals","Speed checks","We also take over websites and bots built by others"],"$h":{"name":"401yen","short":"wvgfhq","description":"1wddnlg","features":"1gwfb2v"}}}'),
