UPDATE services SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Аудит сайта, бота и приложения","short":"Проверяем ваш сайт, бот или приложение, сообщаем об ошибках и пишем техническое описание для их исправления.","description":"Проверяем сайт, Telegram-бот или приложение глазами клиента и с технической стороны. Понятным языком объясняем найденные ошибки, пишем техническое описание для их исправления и рассчитываем стоимость. Исправление можно поручить нам или другому разработчику. Если поручите нам, стоимость аудита вычитается из цены исправлений.","features":["Проверка на телефоне и компьютере: что не работает и что неудобно","Проверка форм, кнопок, оформления заказа и оплаты","Скорость и время загрузки","Безопасность: SSL, устаревшие версии, открытые данные","Ошибки в текстах, картинках и ссылках","Каждая ошибка — со скриншотом, по степени важности","Техническое описание, понятное любому разработчику","Стоимость и сроки исправлений"],"$h":{"name":"1eed2kg","short":"6s4m0f","description":"8ak451","features":"5zg8l"}},"en":{"name":"Website, bot and app audit","short":"We review your website, bot or app, report the issues and write a technical spec for fixing them.","description":"We review your website, Telegram bot or app from a customer’s point of view and technically. We explain the issues in plain language, write a technical spec for fixing them and estimate the cost. You can hand the fixes to us or to another developer. If you choose us, the audit fee is deducted from the cost of the fixes.","features":["Testing on phone and desktop: what’s broken and what’s inconvenient","Testing forms, buttons, checkout and payments","Speed and load time","Security: SSL, outdated versions, exposed data","Errors in text, images and links","Every issue with a screenshot, ranked by severity","A technical spec any developer can follow","Cost and timeline of the fixes"],"$h":{"name":"1eed2kg","short":"6s4m0f","description":"8ak451","features":"5zg8l"}}}'),
  '$.packages[0].i18n', json('{"ru":{"name":"Сайт","features":["Отображение на разных телефонах и в браузерах","Базовые настройки для Google и Яндекса: заголовки, описания, sitemap"],"fit":"Хочу проверить свой сайт","$h":{"name":"c7tuvw","features":"1cll4k9","fit":"tn292o"}},"en":{"name":"Website","features":["How it looks on different phones and browsers","Basic Google and Yandex settings: titles, descriptions, sitemap"],"fit":"I want my website checked","$h":{"name":"c7tuvw","features":"1cll4k9","fit":"tn292o"}}}'),
  '$.packages[1].i18n', json('{"ru":{"name":"Telegram-бот","features":["Проверяем все меню, кнопки и шаги","Ситуации, когда бот перестаёт отвечать","Правильная доставка заказов и уведомлений"],"fit":"Хочу проверить своего бота","$h":{"name":"173h46j","features":"1cblvzy","fit":"6q3rma"}},"en":{"name":"Telegram bot","features":["We tap through every menu, button and step","Cases where the bot stops responding","Orders and notifications are delivered correctly"],"fit":"I want my bot checked","$h":{"name":"173h46j","features":"1cblvzy","fit":"6q3rma"}}}'),
  '$.packages[2].i18n', json('{"ru":{"name":"Приложение","features":["Основные рабочие процессы веб- или мобильного приложения","Пользователи, роли и права доступа","Резервные копии данных и защищённый вход"],"fit":"Хочу проверить своё приложение или программу","$h":{"name":"1m04j1k","features":"whfnm2","fit":"13uqzut"}},"en":{"name":"App","features":["Core workflows of the web or mobile app","Users, roles and permissions","Data backups and secure sign-in"],"fit":"I want my app or software checked","$h":{"name":"1m04j1k","features":"whfnm2","fit":"13uqzut"}}}'),
  '$.examples[0].i18n', json('{"ru":{"name":"UX-аудит сайта трубного завода","owner":"Дальневосточный трубный завод · Россия","text":"Сайт проверили по данным Яндекс Метрики и 3 пользовательским сценариям: цель — найти цену, диаметр и сертификат за 2–3 клика. После аудита сайт создали заново.","image":"/media/public/619fc5f5-d4fb-4bda-89e9-f02e838f8c21.webp","imageMobile":"/media/public/f02ccc11-6a3d-428f-a9b7-69e6ddc47f4f.webp","$h":{"name":"1qy7si6","owner":"exqq1g","text":"14uqr01"}},"en":{"name":"UX audit of a pipe plant’s website","owner":"Far Eastern Pipe Plant · Russia","text":"The site was reviewed using Yandex Metrica data and 3 user scenarios, aiming to find price, diameter and certificate in 2–3 clicks. After the audit, the site was rebuilt.","image":"/media/public/bc9ff6e7-0cd0-4899-950f-c6da7964368f.webp","imageMobile":"/media/public/37942fa8-a065-47e1-ab1c-6f5db801db84.webp","$h":{"name":"1qy7si6","owner":"exqq1g","text":"14uqr01"}}}'),
  '$.examples[1].i18n', json('{"ru":{"name":"Комплексный аудит: 96 страниц","owner":"Студия цифровых решений · Россия","text":"Сайт проверили по 7 направлениям и подготовили отчёт на 96 страниц и план работ на 1, 6 и 12 месяцев.","image":"/media/public/0a1fb029-2ac8-4358-86e5-3f6275b72bed.webp","$h":{"name":"ubvyl9","owner":"n7o3hd","text":"1vmqc70"}},"en":{"name":"Full audit: 96 pages","owner":"Digital solutions studio · Russia","text":"The site was reviewed across 7 areas, producing a 96-page report and a work plan for 1, 6 and 12 months.","image":"/media/public/8282abfe-76d8-4a6b-8bcf-daa49e56ad7a.webp","$h":{"name":"ubvyl9","owner":"n7o3hd","text":"1vmqc70"}}}'),
  '$.examples[2].i18n', json('{"ru":{"name":"Google PageSpeed Insights","owner":"Google · США","text":"Измеряет, насколько быстро страница открывается на телефоне и компьютере, и показывает, что нужно исправить.","image":"/media/public/ab24aa0c-cee2-4b2c-94ae-f74f1c908046.webp","imageMobile":"/media/public/02539bf0-ea6d-4988-b9d8-48b498560456.webp","$h":{"name":"1cv7trd","owner":"h5as6s","text":"1my4pfc"}},"en":{"name":"Google PageSpeed Insights","owner":"Google · USA","text":"Measures how fast a page loads on phone and desktop and shows what needs fixing.","image":"/media/public/406abe1b-a3c9-4a6a-b336-872373bfdf64.webp","imageMobile":"/media/public/6a22f08b-d177-4f30-8a37-6f9080897883.webp","$h":{"name":"1cv7trd","owner":"h5as6s","text":"1my4pfc"}}}'),
  '$.examples[3].i18n', json('{"ru":{"name":"MDN HTTP Observatory","owner":"Mozilla · США","text":"Проверяет настройки безопасности сайта. Проведено 47 миллионов проверок 6,9 миллиона сайтов.","image":"/media/public/10b8011a-7c09-4ba4-b6ee-23ea29b8eb5b.webp","$h":{"name":"l9m55a","owner":"1xiqrj7","text":"b19frm"}},"en":{"name":"MDN HTTP Observatory","owner":"Mozilla · USA","text":"Checks a website’s security settings. It has run 47 million scans of 6.9 million websites.","image":"/media/public/8d8c977d-8be3-4f64-9863-0efa6c88d59c.webp","$h":{"name":"l9m55a","owner":"1xiqrj7","text":"b19frm"}}}'))
