UPDATE services SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Реклама в Telegram и Instagram","short":"Настраиваем и запускаем рекламу в Telegram Ads и Instagram и следим за результатом.","description":"Настраиваем рекламу в Telegram Ads и Instagram, чтобы привести нужных людей на ваш сайт, в бот или канал. Определяем аудиторию, открываем рекламный кабинет, запускаем рекламу и следим за результатом. Если результат слабый, меняем настройки и показываем в отчёте, что было сделано.","features":["Определение цели и аудитории: кто, где, на каком языке","Открытие и настройка рекламного кабинета","Подготовка сайта, бота или канала к рекламе","Запуск рекламы","Отслеживание результата: показы, клики и заявки","Изменение настроек, если результат слабый","Отчёт: что сделано и какой результат","Рекламный бюджет не входит в стоимость услуги: клиент оплачивает его площадке сам или это согласуется отдельно"],"$h":{"name":"1y8olf6","short":"hqb8cp","description":"1jynoca","features":"ln7pjz"}},"en":{"name":"Telegram and Instagram advertising","short":"We set up and launch ads on Telegram Ads and Instagram and track the results.","description":"We set up Telegram Ads and Instagram campaigns to bring the right people to your website, bot or channel. We define the audience, open the ad account, launch the campaign and keep track of the results. If results are weak, we adjust the settings and show what was done in a report.","features":["Defining the goal and audience: who, where and in which language","Opening and setting up the ad account","Preparing your website, bot or channel for the campaign","Launching the ads","Tracking results: impressions, clicks and leads","Adjusting settings if results are weak","Report: what was done and what it achieved","The ad budget isn’t included in the service price: the client pays the platform directly, or it’s agreed separately"],"$h":{"name":"1y8olf6","short":"hqb8cp","description":"1jynoca","features":"ln7pjz"}}}'),
