UPDATE courses SET data = json_set(data,
  '$.i18n', json('{"ru":{"title":"Создание сайтов и ботов с помощью AI","tagline":"На практике научитесь ставить задачи AI-ассистенту, проверять написанный им код и запускать проект.","description":"На курсе вы научитесь правильно объяснять задачу AI-ассистенту, проверять написанный им код и выкладывать готовый проект в интернет. На каждом занятии вы работаете над настоящим проектом.","format":"Онлайн","contents":["Настройка AI-ассистента","Как превратить идею в задачу","Создание сайта","Создание Telegram-бота","Исправление ошибок","Публикация в интернете"],"need":"Хочу научиться делать сам","$h":{"title":"ywlnxn","tagline":"vdtqel","description":"103bs69","format":"kq0vhg","contents":"1fskqf4","need":"1nh72ga"}},"en":{"title":"Building websites and bots with AI","tagline":"Learn hands-on how to brief an AI assistant, review the code it writes and launch your project.","description":"In this course you’ll learn to explain a task clearly to an AI assistant, review the code it writes and publish the finished project online. Every lesson is spent working on a real project.","format":"Online","contents":["Setting up an AI assistant","Turning an idea into a task","Building a website","Building a Telegram bot","Fixing bugs","Publishing online"],"need":"I want to learn to build it myself","$h":{"title":"ywlnxn","tagline":"vdtqel","description":"103bs69","format":"kq0vhg","contents":"1fskqf4","need":"1nh72ga"}}}'),
  '$.steps[0].i18n', json('{"ru":{"title":"Планирование","text":"Превращаете идею в чёткую задачу, понятную AI.","$h":{"title":"1otxds2","text":"1wovqmk"}},"en":{"title":"Planning","text":"You turn your idea into a clear task the AI can understand.","$h":{"title":"1otxds2","text":"1wovqmk"}}}'),
  '$.steps[1].i18n', json('{"ru":{"title":"Пишем вместе с AI","text":"AI-ассистент пишет код, а вы проверяете каждый шаг.","$h":{"title":"qxby97","text":"10xyvbs"}},"en":{"title":"Writing with AI","text":"The AI assistant writes the code while you review every step.","$h":{"title":"qxby97","text":"10xyvbs"}}}'),
  '$.steps[2].i18n', json('{"ru":{"title":"Запуск","text":"Публикуете готовый проект в интернете и делитесь им с другими.","$h":{"title":"kpnbbu","text":"f9p4gi"}},"en":{"title":"Launch","text":"You publish the finished project online and share it with others.","$h":{"title":"kpnbbu","text":"f9p4gi"}}}'))
