UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Система клиентов и заказов","summary":"Клиенты, заказы, задолженности и задачи сотрудников — в одном месте. Вы всегда видите, на каком этапе каждый заказ.","description":"Система собирает в одном месте работу, разбросанную по Excel, тетрадям и чатам. История, заказы и долг каждого клиента — на одной странице. Сотрудники видят свои задачи, руководитель — отчёты за день и месяц. Через Telegram-помощника можно добавить заказ, сменить статус и получить напоминание с телефона в несколько нажатий.","purpose":"Чтобы данные не терялись, клиентам перезванивали вовремя, а состояние бизнеса было видно в цифрах.","features":["База клиентов: контакты, история, заказы, долг","Заказы по этапам: новый, в работе, готов, сдан","Задачи и сроки для сотрудников","Роли: руководитель, менеджер, сотрудник — у каждого свои права","Telegram-помощник: добавить заказ, статус, напоминание","Автоматические сообщения клиенту о статусе","Отчёты за день и месяц, графики","Перенос старых данных из Excel и регулярное резервное копирование"],"platforms":["Веб-приложение","Telegram-бот"],"problem":"Список клиентов — в телефоне одного сотрудника, заказы — в Excel, долги — в тетради. Уходит сотрудник — уходят и данные. Чтобы понять, как прошёл месяц, руководитель вечерами сводит таблицы.","customerView":["Своевременные уведомления о статусе заказа","Напоминания перезвонить клиенту","Сотрудник, который знает историю клиента"],"ownerView":["Все клиенты и заказы в одном месте","Задачи и сроки сотрудников","Сводка за день в Telegram","Выручка за месяц, долги и графики"],"fit":["Производственные цеха","Мебель и ремонт","Оптовая и розничная торговля","Сервисные компании","Учебные центры","Рекламные агентства"],"$h":{"name":"86984o","summary":"qcr3gm","description":"zs7phl","purpose":"g9qje5","features":"1fhzjiz","platforms":"xui4bm","problem":"g81rbg","customerView":"132vkn3","ownerView":"165l4mm","fit":"1694pei"}},"en":{"name":"Customer and order system","summary":"Customers, orders, debts and staff tasks in one place. You always see what stage every order is at.","description":"The system brings together work scattered across Excel, notebooks and chats. Each customer’s history, orders and balance are on one page. Staff see their tasks, and the manager sees daily and monthly reports. With the Telegram helper you can add an order, change its status and get reminders from your phone in a few taps.","purpose":"So no data gets lost, customers get called back on time and the state of the business is visible in numbers.","features":["Customer database: contacts, history, orders, balance","Orders by stage: new, in progress, ready, delivered","Tasks and deadlines for staff","Roles: owner, manager, staff — each with their own permissions","Telegram helper: add orders, update status, get reminders","Automatic status messages to customers","Daily and monthly reports with charts","Migration of old Excel data and regular backups"],"platforms":["Web app","Telegram bot"],"problem":"The customer list is on one employee’s phone, orders are in Excel, debts are in a notebook. When an employee leaves, the data leaves too. To see how the month went, the owner spends evenings stitching spreadsheets together.","customerView":["Timely updates on order status","Reminders to call the customer back","A staff member who knows their history"],"ownerView":["All customers and orders in one place","Staff tasks and deadlines","Daily summary in Telegram","Monthly revenue, debts and charts"],"fit":["Production workshops","Furniture and renovation","Wholesale and retail","Service companies","Training centers","Advertising agencies"],"$h":{"name":"86984o","summary":"qcr3gm","description":"zs7phl","purpose":"g9qje5","features":"1fhzjiz","platforms":"xui4bm","problem":"g81rbg","customerView":"132vkn3","ownerView":"165l4mm","fit":"1694pei"}}}'),
  '$.demo.i18n', json('{"ru":{"bot":"Уста Мебель · CRM","$h":{"bot":"os3ily"}},"en":{"bot":"Usta Furniture · CRM","$h":{"bot":"os3ily"}}}'),
