  '$.demo.nodes[8].owner.i18n', json('{"ru":{"title":"Задача: Севара","lines":["Звонок: Акмал Тошев, №198","Срок: сегодня 16:00"],"$h":{"title":"8sz6zm","lines":"1tztdar"}},"en":{"title":"Task: Sevara","lines":["Call: Akmal Toshev, #198","Due: today 16:00"],"$h":{"title":"8sz6zm","lines":"1tztdar"}}}'),
