  '$.steps[0].i18n', json('{"ru":{"title":"Изучение","text":"Смотрим на ваш рабочий процесс и определяем нужные этапы и поля.","$h":{"title":"kyxfhi","text":"vmjni5"}},"en":{"title":"Discovery","text":"We look at your workflow and define the stages and fields you need.","$h":{"title":"kyxfhi","text":"vmjni5"}}}'),
  '$.steps[1].i18n', json('{"ru":{"title":"Перенос","text":"Переносим клиентов и заказы из Excel и тетрадей в систему.","$h":{"title":"egjfmf","text":"1unpy5w"}},"en":{"title":"Migration","text":"We move customers and orders from Excel and notebooks into the system.","$h":{"title":"egjfmf","text":"1unpy5w"}}}'),
  '$.steps[2].i18n', json('{"ru":{"title":"Роли","text":"У каждого сотрудника свои права: кто что видит и меняет.","$h":{"title":"qdlr3h","text":"s63aj0"}},"en":{"title":"Roles","text":"Each staff member gets their own permissions: who sees and changes what.","$h":{"title":"qdlr3h","text":"s63aj0"}}}'),
  '$.steps[3].i18n', json('{"ru":{"title":"Повседневная работа","text":"Заказы и задачи ведутся в системе или через Telegram-помощника.","$h":{"title":"1p233sq","text":"uim8ky"}},"en":{"title":"Daily work","text":"Orders and tasks are managed in the system or via the Telegram helper.","$h":{"title":"1p233sq","text":"uim8ky"}}}'),
  '$.steps[4].i18n', json('{"ru":{"title":"Отчёт","text":"Руководитель получает сводку за день и отчёт за месяц.","$h":{"title":"tapo35","text":"14mf2ve"}},"en":{"title":"Reports","text":"The owner gets a daily summary and a monthly report.","$h":{"title":"tapo35","text":"14mf2ve"}}}'),
  '$.beforeAfter[0].i18n', json('{"ru":{"before":"Клиенты — в телефоне сотрудника","after":"Все данные — в системе компании","$h":{"before":"1koex3z","after":"iu6zpl"}},"en":{"before":"Customers live on an employee’s phone","after":"All data lives in the company system","$h":{"before":"1koex3z","after":"iu6zpl"}}}'),
  '$.beforeAfter[1].i18n', json('{"ru":{"before":"Клиент звонит узнать статус","after":"Клиенту приходит сообщение, как только статус меняется","$h":{"before":"qrwbsy","after":"8ot8wf"}},"en":{"before":"Customers call to ask about status","after":"Customers get a message as soon as the status changes","$h":{"before":"qrwbsy","after":"8ot8wf"}}}'),
  '$.beforeAfter[2].i18n', json('{"ru":{"before":"Таблицы для отчёта собирают вручную","after":"Отчёт готов каждый день","$h":{"before":"ofwi4m","after":"10auhax"}},"en":{"before":"Report spreadsheets are compiled by hand","after":"The report is ready every day","$h":{"before":"ofwi4m","after":"10auhax"}}}'),
  '$.beforeAfter[3].i18n', json('{"ru":{"before":"Долги в тетради забываются","after":"О просроченном долге приходит напоминание","$h":{"before":"1fecisq","after":"tep3dr"}},"en":{"before":"Debts in a notebook get forgotten","after":"Overdue balances trigger a reminder","$h":{"before":"1fecisq","after":"tep3dr"}}}'),
  '$.faq[0].i18n', json('{"ru":{"q":"Чем это отличается от готовой CRM (amoCRM, Bitrix24)?","a":"У готовых CRM много возможностей, но они сложные и с ежемесячной подпиской. Эта система делается только с нужными вам полями и этапами, а код и данные принадлежат вам.","$h":{"q":"p3djoy","a":"1p367xb"}},"en":{"q":"How is this different from an off-the-shelf CRM (amoCRM, Bitrix24)?","a":"Off-the-shelf CRMs have lots of features, but they’re complex and need a monthly subscription. This system is built with only the fields and stages you need, and the code and data are yours.","$h":{"q":"p3djoy","a":"1p367xb"}}}'),
  '$.faq[1].i18n', json('{"ru":{"q":"Можно ли работать с телефона?","a":"Да, система адаптирована под телефон, а самые частые действия есть и в Telegram-помощнике.","$h":{"q":"1mgt35c","a":"1pf6ztt"}},"en":{"q":"Can I use it from my phone?","a":"Yes, the system is mobile-friendly, and the most common actions are also in the Telegram helper.","$h":{"q":"1mgt35c","a":"1pf6ztt"}}}'),
  '$.faq[2].i18n', json('{"ru":{"q":"Не потеряются ли наши данные?","a":"Регулярно делаются резервные копии, а вход защищён паролем и ролями.","$h":{"q":"zkw2nj","a":"55jwrd"}},"en":{"q":"Could we lose our data?","a":"Regular backups are made, and access is protected by passwords and roles.","$h":{"q":"zkw2nj","a":"55jwrd"}}}'))
