UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"DALOLAT","summary":"Приложение в Telegram, которое помогает найти достойную пару.","description":"DALOLAT — приложение, которое работает внутри Telegram (Mini App). Помогает найти достойную пару в соответствии с религиозными ценностями: лента подбирается под ваши требования, в каждой анкете виден процент совместимости, вы отправляете кандидату запрос, и если он его примет, общаетесь прямо в приложении.","purpose":"Помочь людям, которые хотят создать семью, найти достойную пару с уважением, доверием и конфиденциальностью.","features":["Процент совместимости, фильтры и поиск по ID","Синяя галочка — анкеты с проверенным живым лицом","Фото открываются только тем, кому вы разрешили","AI-ассистент Нур и тест характера (Big Five)","Общение при свидетеле и личная сваха","5 языков: узбекский, русский, английский, турецкий, арабский"],"platforms":["Telegram Mini App","dalolat.app"],"seoTitle":"DALOLAT — Достойная пара, крепкая семья","seoDescription":"DALOLAT — приложение в Telegram: процент совместимости, проверенные анкеты, скрытые фото и AI-ассистент Нур помогают найти достойную пару.","$h":{"name":"25gmnk","summary":"8kuhyk","description":"7jh7cl","purpose":"17a6ivj","features":"183i9p","platforms":"a0as8u","seoTitle":"jro73i","seoDescription":"15n79qo"}},"en":{"name":"DALOLAT","summary":"A Telegram app that helps you find the right spouse.","description":"DALOLAT is an app that runs inside Telegram (a Mini App). It helps you find the right spouse in line with religious values: the feed is sorted by your preferences, every profile shows a compatibility score, you send a request to a candidate, and if they accept, you chat right inside the app.","purpose":"To help people who want to start a family find the right spouse with respect, trust and privacy.","features":["Compatibility score, filters and search by ID","Blue badge — profiles with a live face check","Photos open only to people you approve","Nur AI assistant and a personality test (Big Five)","Chats with a chaperone and a personal matchmaker","5 languages: Uzbek, Russian, English, Turkish, Arabic"],"platforms":["Telegram Mini App","dalolat.app"],"seoTitle":"DALOLAT — The right spouse, a strong family","seoDescription":"DALOLAT is a Telegram app: compatibility scores, verified profiles, private photos and the Nur AI assistant help you find the right spouse.","$h":{"name":"25gmnk","summary":"8kuhyk","description":"7jh7cl","purpose":"17a6ivj","features":"183i9p","platforms":"a0as8u","seoTitle":"jro73i","seoDescription":"15n79qo"}}}'))
WHERE slug = 'dalolat';

UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Бот для заказа еды","summary":"Клиент выбирает блюда в меню, отправляет адрес и выбирает способ оплаты. Заказ уходит на кухню и курьеру.","description":"В боте клиент смотрит меню в Telegram, выбирает блюда, отправляет адрес геолокацией и оплачивает. Заказ уходит на кухню, а когда готов — курьеру. На каждом этапе клиент получает уведомление, а после доставки оставляет оценку.","purpose":"Меньше звонков и ошибок в записанных от руки заказах, быстрее доставка.","features":["Меню с фото и блюдо дня","Корзина и добавки","Отправка адреса геолокацией и расчёт стоимости доставки","Оплата через Payme, Click или наличными","Отдельный чат для кухни и курьеров","Статус: принят, готовится, в пути, доставлен","Запрос оценки и отзыва после доставки","Повтор прошлого заказа в одно нажатие"],"platforms":["Telegram-бот","Telegram Mini App"],"problem":"В обед телефон не умолкает: оператор записывает заказ, уточняет адрес и передаёт на кухню на бумаге. В спешке теряется блюдо или путается адрес, а клиент снова и снова звонит: «когда привезёте?».","customerView":["Меню с фото и ценами","Стоимость и примерное время доставки","На каком этапе заказ","Кнопка повтора прошлого заказа"],"ownerView":["Кухня: состав нового заказа","Курьер: адрес, телефон и статус оплаты","В конце дня: число заказов, выручка, оценки","Самые продаваемые блюда"],"fit":["Кафе национальной кухни","Фастфуд","Кафе и рестораны","Домашние кухни","Пекарни и кондитерские","Доставка обедов в офисы"],"$h":{"name":"r4wgvf","summary":"4t202r","description":"10xjqvb","purpose":"1uz61z","features":"yyfqqh","platforms":"1pn6zn6","problem":"7oimvh","customerView":"1c7q5o2","ownerView":"16ma4xr","fit":"gozwlm"}},"en":{"name":"Food ordering bot","summary":"Customers pick dishes from the menu, send their address and choose how to pay. The order goes to the kitchen and the courier.","description":"In the bot, customers browse the menu in Telegram, pick dishes, share their location and pay. The order goes to the kitchen and, once ready, to a courier. Customers get updates at every stage and leave a rating after delivery.","purpose":"Fewer phone calls and fewer mistakes in hand-written orders, plus faster delivery.","features":["Menu with photos and a dish of the day","Cart and add-ons","Address via location sharing and delivery fee calculation","Payment via Payme, Click or cash","Separate chats for the kitchen and couriers","Status: received, cooking, on the way, delivered","Rating and feedback request after delivery","Repeat a previous order in one tap"],"platforms":["Telegram bot","Telegram Mini App"],"problem":"At lunchtime the phone never stops: the operator writes down the order, asks for the address and passes it to the kitchen on paper. In the rush a dish gets missed or the address gets mixed up, and the customer keeps calling to ask “when will it arrive?”.","customerView":["Menu with photos and prices","Delivery fee and estimated time","Which stage the order is at","A button to repeat a previous order"],"ownerView":["Kitchen: contents of each new order","Courier: address, phone and payment status","End of day: number of orders, revenue, ratings","Best-selling dishes"],"fit":["Uzbek cuisine restaurants","Fast food","Cafes and restaurants","Home kitchens","Bakeries and pastry shops","Office lunch delivery"],"$h":{"name":"r4wgvf","summary":"4t202r","description":"10xjqvb","purpose":"1uz61z","features":"yyfqqh","platforms":"1pn6zn6","problem":"7oimvh","customerView":"1c7q5o2","ownerView":"16ma4xr","fit":"gozwlm"}}}'),
  '$.demo.i18n', json('{"ru":{"bot":"Чайхана «Навруз»","$h":{"bot":"1xr4pua"}},"en":{"bot":"Navruz Teahouse","$h":{"bot":"1xr4pua"}}}'),
