  '$.steps[0].i18n', json('{"ru":{"title":"Меню","text":"Вносим блюда, цены, фото и зону доставки.","$h":{"title":"o18lo9","text":"al0sdu"}},"en":{"title":"Menu","text":"We add dishes, prices, photos and the delivery area.","$h":{"title":"o18lo9","text":"al0sdu"}}}'),
  '$.steps[1].i18n', json('{"ru":{"title":"Заказ","text":"Клиент выбирает блюда, отправляет геолокацию и оплачивает.","$h":{"title":"1543qta","text":"10xrcod"}},"en":{"title":"Order","text":"The customer picks dishes, shares their location and pays.","$h":{"title":"1543qta","text":"10xrcod"}}}'),
  '$.steps[2].i18n', json('{"ru":{"title":"Кухня","text":"Заказ попадает в чат кухни; повар нажимает «готово».","$h":{"title":"1gnps9d","text":"1y8rbvu"}},"en":{"title":"Kitchen","text":"The order lands in the kitchen chat; the cook taps “ready”.","$h":{"title":"1gnps9d","text":"1y8rbvu"}}}'),
  '$.steps[3].i18n', json('{"ru":{"title":"Курьер","text":"Курьер забирает заказ, клиенту приходит сообщение «в пути».","$h":{"title":"1pcic17","text":"ezcrpw"}},"en":{"title":"Courier","text":"The courier picks up the order, and the customer gets an “on the way” message.","$h":{"title":"1pcic17","text":"ezcrpw"}}}'),
