  '$.beforeAfter[0].i18n', json('{"ru":{"before":"Заказ записывают вручную по телефону","after":"Клиент выбирает сам, состав приходит без ошибок","$h":{"before":"s6gn4v","after":"we98d6"}},"en":{"before":"Orders are written down by hand over the phone","after":"Customers choose themselves, and orders arrive error-free","$h":{"before":"s6gn4v","after":"we98d6"}}}'),
  '$.beforeAfter[1].i18n', json('{"ru":{"before":"Адрес объясняют на словах","after":"Курьер получает точку на карте","$h":{"before":"1rh62gy","after":"dtjkt7"}},"en":{"before":"Addresses are explained verbally","after":"The courier gets an exact pin on the map","$h":{"before":"1rh62gy","after":"dtjkt7"}}}'),
  '$.beforeAfter[2].i18n', json('{"ru":{"before":"Клиент звонит: «когда привезёте?»","after":"Он сам получает уведомления на каждом этапе","$h":{"before":"1ttkgfg","after":"tmx1th"}},"en":{"before":"Customers call to ask “when will it arrive?”","after":"They get updates at every stage","$h":{"before":"1ttkgfg","after":"tmx1th"}}}'),
  '$.beforeAfter[3].i18n', json('{"ru":{"before":"Отзывы не собираются","after":"После каждой доставки есть оценка","$h":{"before":"1aecnyr","after":"1li37qe"}},"en":{"before":"Feedback isn’t collected","after":"Every delivery gets a rating","$h":{"before":"1aecnyr","after":"1li37qe"}}}'),
  '$.faq[0].i18n', json('{"ru":{"q":"Как считается стоимость доставки?","a":"По расстоянию или по зоне — как вы решите. Когда клиент отправит геолокацию, цена появится автоматически.","$h":{"q":"1oavj2q","a":"wmu9os"}},"en":{"q":"How is the delivery fee calculated?","a":"By distance or by zone — whichever you choose. Once the customer shares their location, the price appears automatically.","$h":{"q":"1oavj2q","a":"wmu9os"}}}'),
  '$.faq[1].i18n', json('{"ru":{"q":"Работает ли с нашими курьерами?","a":"Да, курьеры получают заказы в отдельном чате или боте и меняют статус одной кнопкой.","$h":{"q":"1vtk0t4","a":"2yf0v6"}},"en":{"q":"Does it work with our own couriers?","a":"Yes, couriers receive orders in a separate chat or bot and update the status with one tap.","$h":{"q":"1vtk0t4","a":"2yf0v6"}}}'),
  '$.faq[2].i18n', json('{"ru":{"q":"Мы часто меняем меню — это сложно?","a":"Блюдо, цену и отметку «закончилось» вы меняете в админ-панели за минуту.","$h":{"q":"1bpy67x","a":"yzkju"}},"en":{"q":"We change our menu often — is that hard?","a":"You change a dish, its price or the “sold out” mark in the admin panel in a minute.","$h":{"q":"1bpy67x","a":"yzkju"}}}'))
