UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Система оптовых заказов","summary":"Постоянные покупатели видят свои цены, наличие товаров и задолженность. Заказы передаются в вашу учётную систему.","description":"Кабинет в Telegram для постоянных покупателей — магазинов, ресторанов и других. Клиент входит по номеру телефона и видит только свои цены, остатки на складе и задолженность. Прошлый заказ повторяет одним нажатием. Заказы связаны с вашей учётной системой (1C, МойСклад).","purpose":"Принимать оптовые заказы от агентов и по телефону быстрее, с меньшим числом ошибок и круглосуточно.","features":["Вход по номеру телефона — посторонние не увидят цены","У каждого клиента свой тип цены и скидка","Остатки на складе в реальном времени","Повтор прошлого заказа в одно нажатие","Задолженность и срок оплаты","Уведомления об акциях и новых товарах","Связь с 1C или МойСклад","Панель заказов для агентов"],"platforms":["Telegram-бот","Telegram Mini App","1C / МойСклад"],"problem":"Оптовые клиенты каждую неделю диктуют по телефону один и тот же список, а менеджер переписывает его заново. Непонятно, какой товар остался, цены у каждого клиента свои — ошибиться легко. А задолженность ведётся в отдельной тетради.","customerView":["Только свои цены","Остатки товаров","Задолженность и срок оплаты","История заказов и повтор"],"ownerView":["Каждый заказ — в учётной системе","Продажи и долги по клиентам","Клиенты, давно не делавшие заказов","Заказы в разрезе агентов"],"fit":["Дистрибьюторы продуктов","Оптовая торговля стройматериалами","Поставщики напитков и воды","Хозяйственные товары","Канцтовары","Производственные предприятия"],"$h":{"name":"o9h4l2","summary":"8go9ej","description":"l08h12","purpose":"1kyesat","features":"1if45jc","platforms":"fjlet2","problem":"13mkwfm","customerView":"g1pbx1","ownerView":"ynjkv2","fit":"slnt9"}},"en":{"name":"Wholesale ordering system","summary":"Your regular buyers see their own prices, product availability and outstanding balance. Orders flow into your accounting system.","description":"A Telegram account area for regular buyers such as shops and restaurants. Customers sign in with their phone number and see only their own prices, warehouse stock and outstanding balance. They repeat a previous order in one tap. Orders are connected to your accounting system (1C, MoySklad).","purpose":"To take wholesale orders from agents and over the phone faster, with fewer mistakes, around the clock.","features":["Phone-number sign-in — outsiders can’t see your prices","Each customer has their own price tier and discount","Real-time warehouse stock","Repeat a previous order in one tap","Outstanding balance and payment due date","Notifications about promotions and new products","1C or MoySklad integration","Order dashboard for sales agents"],"platforms":["Telegram bot","Telegram Mini App","1C / MoySklad"],"problem":"Wholesale customers read out the same list over the phone every week, and a manager types it up again. Nobody knows what’s left in stock, prices differ per customer — mistakes are easy. And the debts live in a separate notebook.","customerView":["Only their own prices","Product stock","Outstanding balance and due date","Order history and repeat orders"],"ownerView":["Every order in your accounting system","Sales and debt by customer","Customers who haven’t ordered in a while","Orders broken down by agent"],"fit":["Food distributors","Wholesale building materials","Beverage and water suppliers","Household goods","Office supplies","Manufacturers"],"$h":{"name":"o9h4l2","summary":"8go9ej","description":"l08h12","purpose":"1kyesat","features":"1if45jc","platforms":"fjlet2","problem":"13mkwfm","customerView":"g1pbx1","ownerView":"ynjkv2","fit":"slnt9"}}}'),
