  '$.steps[0].i18n', json('{"ru":{"title":"Подключение","text":"Берём товары, типы цен и остатки из вашей учётной системы.","$h":{"title":"1cx0qwk","text":"7rs918"}},"en":{"title":"Connect","text":"We pull products, price tiers and stock from your accounting system.","$h":{"title":"1cx0qwk","text":"7rs918"}}}'),
  '$.steps[1].i18n', json('{"ru":{"title":"Клиенты","text":"Каждому клиенту по номеру телефона назначаются тип цены и кредитный лимит.","$h":{"title":"1gebj89","text":"xz24se"}},"en":{"title":"Customers","text":"Each customer is linked by phone number to a price tier and a credit limit.","$h":{"title":"1gebj89","text":"xz24se"}}}'),
  '$.steps[2].i18n', json('{"ru":{"title":"Заказ","text":"Клиент выбирает из каталога или повторяет прошлый заказ.","$h":{"title":"1543qta","text":"jcqx0l"}},"en":{"title":"Order","text":"The customer picks from the catalog or repeats a past order.","$h":{"title":"1543qta","text":"jcqx0l"}}}'),
  '$.steps[3].i18n', json('{"ru":{"title":"Проверка","text":"Бот проверяет остатки и кредитный лимит.","$h":{"title":"8uho84","text":"qvcjkl"}},"en":{"title":"Checks","text":"The bot checks stock and the credit limit.","$h":{"title":"8uho84","text":"qvcjkl"}}}'),
  '$.steps[4].i18n', json('{"ru":{"title":"В учётную систему","text":"Заказ передаётся в 1C или МойСклад и уходит на склад на сборку.","$h":{"title":"axp6ha","text":"5tviug"}},"en":{"title":"To accounting","text":"The order goes to 1C or MoySklad and on to the warehouse for picking.","$h":{"title":"axp6ha","text":"5tviug"}}}'),
  '$.steps[5].i18n', json('{"ru":{"title":"Уведомление","text":"Клиент получает сообщения о том, что заказ собирается и отправлен.","$h":{"title":"1ufb8df","text":"m9i0ha"}},"en":{"title":"Notification","text":"The customer is notified when the order is being prepared and when it ships.","$h":{"title":"1ufb8df","text":"m9i0ha"}}}'),
  '$.beforeAfter[0].i18n', json('{"ru":{"before":"Заказ диктуют по телефону и переписывают","after":"Клиент вводит его сам, и он автоматически попадает в учётную систему","$h":{"before":"cauzfg","after":"phvh9i"}},"en":{"before":"Orders are dictated by phone and retyped","after":"Customers enter them, and they land in accounting automatically","$h":{"before":"cauzfg","after":"phvh9i"}}}'),
  '$.beforeAfter[1].i18n', json('{"ru":{"before":"Чтобы узнать остаток, звонят на склад","after":"Остаток виден прямо в каталоге","$h":{"before":"1t7xpqs","after":"1n6w7fb"}},"en":{"before":"Stock is checked by calling the warehouse","after":"Stock is shown right in the catalog","$h":{"before":"1t7xpqs","after":"1n6w7fb"}}}'),
  '$.beforeAfter[2].i18n', json('{"ru":{"before":"Цену каждого клиента приходится помнить","after":"Тип цены привязан к номеру телефона","$h":{"before":"y8o5pt","after":"1jgsiw1"}},"en":{"before":"Everyone’s prices have to be remembered","after":"The price tier is tied to the phone number","$h":{"before":"y8o5pt","after":"1jgsiw1"}}}'),
  '$.beforeAfter[3].i18n', json('{"ru":{"before":"Долги — в отдельной тетради","after":"Долг и срок видны и клиенту, и вам","$h":{"before":"1l9taoe","after":"6lc5ax"}},"en":{"before":"Debts live in a separate notebook","after":"The balance and due date are visible to both you and the customer","$h":{"before":"1l9taoe","after":"6lc5ax"}}}'),
  '$.faq[0].i18n', json('{"ru":{"q":"Не увидит ли посторонний мои цены?","a":"Нет. Кабинет открывается только для номеров, которые вы добавили, и каждый видит только свои цены.","$h":{"q":"3fyd81","a":"o9qg9y"}},"en":{"q":"Could an outsider see my prices?","a":"No. The account area opens only for phone numbers you’ve added, and each customer sees only their own prices.","$h":{"q":"3fyd81","a":"o9qg9y"}}}'),
  '$.faq[1].i18n', json('{"ru":{"q":"Наша учётная система — 1C. Как она подключается?","a":"Делаем интеграцию с 1C или МойСклад для обмена товарами, остатками и заказами. Сначала проверяем на тестовой базе.","$h":{"q":"146qyvr","a":"8bx49h"}},"en":{"q":"We use 1C for accounting. How does it connect?","a":"We build an integration with 1C or MoySklad that exchanges products, stock and orders. We test it on a trial database first.","$h":{"q":"146qyvr","a":"8bx49h"}}}'),
  '$.faq[2].i18n', json('{"ru":{"q":"Смогут ли пользоваться наши агенты?","a":"Да, агент оформляет заказы от имени своих клиентов, а вы видите отчёт в разрезе агентов.","$h":{"q":"x7z236","a":"1xfanqz"}},"en":{"q":"Can our sales agents use it too?","a":"Yes, agents place orders on behalf of their customers, and you see reports broken down by agent.","$h":{"q":"x7z236","a":"1xfanqz"}}}'))
