UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"AI для проверки письменных и устных ответов","summary":"Разбирает эссе или устный ответ ученика, объясняет ошибки и ставит примерную оценку. Преподаватель следит за работами учеников.","description":"AI оценивает эссе или голосовой ответ ученика по критериям, близким к международным экзаменам: балл по каждому критерию, список ошибок и улучшенный вариант. Преподаватель видит, кому и в чём в группе трудно. Оценка ориентировочная — итоговое решение за преподавателем.","purpose":"Чтобы ученик больше практиковался дома, а преподаватель тратил меньше времени на проверку.","features":["Приём эссе и голосовых ответов","Баллы по критериям: соответствие заданию, связность, лексика, грамматика","Список ошибок с объяснениями","Пример улучшенного варианта","Тема и упражнение на каждый день","Еженедельный отчёт по группе для преподавателя","График прогресса ученика"],"platforms":["Telegram-бот","AI"],"problem":"В языковом центре на одного преподавателя приходятся десятки эссе. Проверка растягивается на дни, а ученик, не дождавшись ответа, бросает практику. Возможности самостоятельно тренировать устную речь почти нет.","customerView":["Ежедневное задание","Балл и комментарий за несколько минут","Ошибки и улучшенный вариант","Свой график прогресса"],"ownerView":["Еженедельный отчёт по группе","По какому критерию группа отстаёт","Ученики, бросившие практику","История работ каждого ученика"],"fit":["Языковые центры","Курсы подготовки к IELTS и CEFR","Школы","Частные преподаватели","Онлайн-курсы"],"$h":{"name":"bz78qo","summary":"367sev","description":"zi0mw3","purpose":"1nhr1rd","features":"15jbdjb","platforms":"1b4w6f5","problem":"10twxi6","customerView":"j6ra4r","ownerView":"zpe31u","fit":"1ngjzxp"}},"en":{"name":"AI that grades written and spoken answers","summary":"Analyzes a student’s essay or spoken answer, explains the mistakes and gives an estimated score. The teacher keeps track of students’ work.","description":"The AI grades a student’s essay or voice answer against criteria close to international exams: a score per criterion, a list of mistakes and an improved version. The teacher sees who in the group struggles with what. The score is a guide — the final call is the teacher’s.","purpose":"So students practice more at home and teachers spend less time grading.","features":["Accepts essays and voice answers","Scores by criterion: task response, coherence, vocabulary, grammar","List of mistakes with explanations","A sample improved version","A daily topic and exercise","Weekly group report for the teacher","Student progress chart"],"platforms":["Telegram bot","AI"],"problem":"In a language center, one teacher gets dozens of essays. Grading drags on for days, and students give up practicing while they wait. There’s almost no way to practice speaking on your own.","customerView":["A daily assignment","A score and comments within minutes","Mistakes and an improved version","A personal progress chart"],"ownerView":["Weekly group report","Which criterion the group is weakest in","Students who stopped practicing","Each student’s work history"],"fit":["Language centers","IELTS and CEFR prep courses","Schools","Private tutors","Online courses"],"$h":{"name":"bz78qo","summary":"367sev","description":"zi0mw3","purpose":"1nhr1rd","features":"15jbdjb","platforms":"1b4w6f5","problem":"10twxi6","customerView":"j6ra4r","ownerView":"zpe31u","fit":"1ngjzxp"}}}'),
