UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Бот учёта посещаемости и задач","summary":"Сотрудники отмечают приход на работу и сдают выполненные задачи. Руководитель видит посещаемость, выполненную работу и запросы на отгул.","description":"Внутренний Telegram-бот, которым сотрудники пользуются каждый день. Сотрудник отмечает приход с геолокацией, получает задачи на день и сдаёт выполненное с фото или комментарием. Запросы на отпуск и отгул — тоже здесь. В конце дня руководитель получает сводку: кто пришёл, кто опоздал и какие задачи не выполнены.","purpose":"Перевести контроль из звонков и хаоса в групповых чатах в одну понятную систему.","features":["Отметка прихода и ухода с геолокацией","Задачи и сроки на день для каждого сотрудника","Сдача задачи с фото или комментарием","Запросы на отпуск, больничный и отгул","Сводка для руководителя в конце дня","Табель посещаемости за месяц — для расчёта зарплаты","По филиалам и отделам"],"platforms":["Telegram-бот","Веб-панель"],"problem":"Кто пришёл на работу, кто опоздал — руководитель выясняет звонками. Задачи дают в общем чате, и они теряются среди сообщений. В конце месяца посещаемость и зарплата становятся предметом споров.","ownerView":["Кто пришёл, кто опоздал — каждое утро","Невыполненные задачи","Запросы на отпуск и отгул — в одну кнопку","Табель посещаемости за месяц"],"fit":["Сети магазинов","Кафе и рестораны","Строительные бригады","Клининговые службы","Производство","Компании с филиалами"],"$h":{"name":"ibendi","summary":"1uk47cf","description":"fwba8t","purpose":"15ytedk","features":"50uyka","platforms":"t02x8x","problem":"ilx6tn","ownerView":"efol4b","fit":"1fxkajs"}},"en":{"name":"Attendance and task bot","summary":"Employees check in when they arrive and hand in completed tasks. The manager sees attendance, finished work and time-off requests.","description":"An internal Telegram bot your team uses every day. Employees check in with their location, get their daily tasks and submit finished work with a photo or comment. Leave and time-off requests live here too. At the end of the day the manager gets a summary: who came in, who was late and which tasks weren’t done.","purpose":"To move oversight from phone calls and chaotic group chats into one clear system.","features":["Check-in and check-out with location","Daily tasks and deadlines for each employee","Submit tasks with a photo or comment","Leave, sick day and time-off requests","End-of-day summary for the manager","Monthly attendance sheet — ready for payroll","By branch and department"],"platforms":["Telegram bot","Web dashboard"],"problem":"The manager finds out who came to work and who was late by calling around. Tasks are handed out in a group chat and get lost among the messages. At the end of the month, attendance and pay turn into arguments.","ownerView":["Who came in and who was late — every morning","Unfinished tasks","Leave and time-off requests in one tap","Monthly attendance sheet"],"fit":["Retail chains","Cafes and restaurants","Construction crews","Cleaning services","Manufacturing","Companies with branches"],"$h":{"name":"ibendi","summary":"1uk47cf","description":"fwba8t","purpose":"15ytedk","features":"50uyka","platforms":"t02x8x","problem":"ilx6tn","ownerView":"efol4b","fit":"1fxkajs"}}}'),
