UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Помощник для подготовки постов","summary":"Готовит темы и тексты постов для вашего бизнеса на неделю. Вы проверяете их и утверждаете или правите.","description":"Помощник составляет недельный план постов на основе вашего бизнеса, продуктов и тона: тема, текст, идея для картинки и время публикации. Каждый понедельник план приходит в Telegram, а вы утверждаете каждый пост, просите переписать или убираете его. Утверждённые посты попадают в контент-календарь в Google Sheets или Notion.","purpose":"Не тратить каждый день время на вопрос «что сегодня выложить?» и вести страницу регулярно.","features":["Тексты под ваш бизнес и ваш тон","Недельный план: тема, текст, идея картинки, время","Каждый пост можно утвердить, переписать или убрать","Учитывает праздники и сезонные даты","Контент-календарь в Google Sheets или Notion","Автоматическая публикация в Telegram-канал","Отдельные форматы для Instagram и Telegram"],"platforms":["Telegram-бот","AI","Notion / Google Sheets"],"problem":"Страница неделями не обновляется: работы много, на посты нет времени. SMM-специалист дорогой или плохо знает бизнес. В итоге посты выходят случайно и похожи друг на друга.","customerView":["Регулярные и упорядоченные посты","Своевременные новости о продуктах и акциях","Единый тон и стиль"],"ownerView":["Готовый недельный план каждый понедельник","Кнопки утверждения для каждого поста","Контент-календарь в Notion или таблице","Готовый текст ко времени публикации"],"fit":["Кафе и рестораны","Салоны красоты","Учебные центры","Интернет-магазины","Личные бренды и эксперты","Клиники"],"$h":{"name":"1r3cm2j","summary":"co6rdi","description":"1rn9c5g","purpose":"r6unzi","features":"3c1ka7","platforms":"ift1m4","problem":"14dm6yi","customerView":"1ev14o6","ownerView":"47rs6h","fit":"vzn93s"}},"en":{"name":"Social media post assistant","summary":"Prepares weekly topics and post copy for your business. You review them and approve or edit.","description":"The assistant builds a weekly post plan based on your business, products and tone of voice: topic, copy, image idea and publishing time. Every Monday the plan arrives in Telegram, and you approve each post, ask for a rewrite or drop it. Approved posts go into a content calendar in Google Sheets or Notion.","purpose":"To stop spending time every day on “what do we post today?” and keep your page active.","features":["Copy tailored to your business and tone","Weekly plan: topic, copy, image idea, time","Approve, rewrite or drop each post","Takes holidays and seasonal dates into account","Content calendar in Google Sheets or Notion","Automatic posting to your Telegram channel","Separate formats for Instagram and Telegram"],"platforms":["Telegram bot","AI","Notion / Google Sheets"],"problem":"The page goes quiet for weeks: there’s too much work and no time to write posts. An SMM specialist is expensive or doesn’t know the business well. As a result, posts are random and look alike.","customerView":["Regular, well-organized posts","Timely news about products and promotions","A consistent tone and style"],"ownerView":["A ready weekly plan every Monday","Approval buttons for every post","Content calendar in Notion or a spreadsheet","Ready copy at publishing time"],"fit":["Cafes and restaurants","Beauty salons","Training centers","Online stores","Personal brands and experts","Clinics"],"$h":{"name":"1r3cm2j","summary":"co6rdi","description":"1rn9c5g","purpose":"r6unzi","features":"3c1ka7","platforms":"ift1m4","problem":"14dm6yi","customerView":"1ev14o6","ownerView":"47rs6h","fit":"vzn93s"}}}'),
