  '$.demo.nodes[4].owner.i18n', json('{"ru":{"title":"План недели готов","lines":["Утверждено 5/5 постов","Канал: автоматически · Instagram: с напоминанием"],"$h":{"title":"f4r1oz","lines":"eoh0pj"}},"en":{"title":"Weekly plan ready","lines":["5/5 posts approved","Channel: automatic · Instagram: with a reminder"],"$h":{"title":"f4r1oz","lines":"eoh0pj"}}}'),
