  '$.steps[1].i18n', json('{"ru":{"title":"План","text":"Каждый понедельник AI составляет план на неделю.","$h":{"title":"r87q59","text":"10uyudl"}},"en":{"title":"Plan","text":"Every Monday the AI drafts a weekly plan.","$h":{"title":"r87q59","text":"10uyudl"}}}'),
