UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Сайт записи и оплаты курса","summary":"Ученик смотрит программу и цену курса и оплачивает. После подтверждения оплаты бот присылает ему ссылку на закрытый Telegram-канал.","description":"Готовая система продаж для онлайн-курса или марафона. На странице — программа курса, автор и тарифы. Когда ученик платит, система сама подтверждает оплату и через Telegram-бота выдаёт одноразовую ссылку в закрытый канал или группу. Перед окончанием подписки напоминает, а неоплативших удаляет из канала.","purpose":"Избавиться от ручной проверки чеков и добавления учеников в канал по одному.","features":["Страница курса: программа, автор, тарифы, вопросы и ответы","Оплата через Payme и Click","После оплаты — одноразовая ссылка в закрытый канал или группу","Ссылка работает для одного человека и один раз","Для месячной подписки — напоминание о сроке и автоматическое удаление","Промокоды и цена раннего бронирования","Список учеников и учёт оплат"],"platforms":["Сайт","Telegram-бот"],"problem":"Когда курс объявлен, директ переполнен: отправляешь номер карты, ждёшь фото чека, потом вручную добавляешь каждого ученика в канал. Кто-то передаёт ссылку другу, кто-то остаётся в канале, не оплатив подписку.","customerView":["Полная страница о курсе","Оплата картой в несколько нажатий","Доступ в канал сразу после оплаты","Напоминание о сроке подписки"],"ownerView":["Уведомление о каждой оплате и новом ученике","Список учеников и тарифов","Подписки, которые скоро закончатся","Результаты промокодов"],"fit":["Авторы онлайн-курсов","Эксперты и блогеры","Марафоны","Закрытые клубы и сообщества","Онлайн-группы учебных центров"],"$h":{"name":"36zl48","summary":"lwiw50","description":"1ezdlj6","purpose":"atm7lp","features":"13t0yt6","platforms":"1bz0o38","problem":"1b7e1bd","customerView":"5w7wqw","ownerView":"16t76zw","fit":"1v229rh"}},"en":{"name":"Course enrollment and payment site","summary":"Students see the course curriculum and price and pay. Once payment is confirmed, the bot sends them a link to a private Telegram channel.","description":"A ready-made sales system for an online course or challenge. The page shows the curriculum, the author and the plans. When a student pays, the system confirms the payment automatically and the Telegram bot issues a one-time link to a private channel or group. It sends a reminder before the subscription ends and removes those who haven’t paid.","purpose":"No more checking receipts by hand or adding students to the channel one by one.","features":["Course page: curriculum, author, plans, FAQ","Payments via Payme and Click","A one-time link to a private channel or group after payment","Each link works for one person, once","For monthly subscriptions — renewal reminders and automatic removal","Promo codes and early-bird pricing","Student list and payment records"],"platforms":["Website","Telegram bot"],"problem":"When a course is announced, DMs overflow: you send your card number, wait for a receipt photo, then add every student to the channel by hand. Someone shares the link with a friend, someone stays in the channel without paying.","customerView":["A complete course page","Card payment in a few taps","Channel access right after payment","Subscription renewal reminders"],"ownerView":["An alert for every payment and new student","List of students and plans","Subscriptions about to expire","Promo code results"],"fit":["Online course creators","Experts and bloggers","Challenges","Private clubs and communities","Online groups of training centers"],"$h":{"name":"36zl48","summary":"lwiw50","description":"1ezdlj6","purpose":"atm7lp","features":"13t0yt6","platforms":"1bz0o38","problem":"1b7e1bd","customerView":"5w7wqw","ownerView":"16t76zw","fit":"1v229rh"}}}'),
