  '$.demo.nodes[6].i18n', json('{"ru":{"messages":["Ваш курс заканчивается через 3 дня. Продолжение — «Мобильная фотография 2» — с 15 декабря. Для записавшихся заранее −15%."],"$h":{"messages":"1hssudh"}},"en":{"messages":["Your course ends in 3 days. The sequel, “Mobile Photography 2”, starts December 15. Early sign-ups get −15%."],"$h":{"messages":"1hssudh"}}}'),
