  '$.steps[3].i18n', json('{"ru":{"title":"Доступ","text":"Бот выдаёт ученику одноразовую ссылку и добавляет его в канал.","$h":{"title":"i5vy3v","text":"ettp3y"}},"en":{"title":"Access","text":"The bot gives the student a one-time link and adds them to the channel.","$h":{"title":"i5vy3v","text":"ettp3y"}}}'),
