  '$.faq[0].i18n', json('{"ru":{"q":"Курс проходит прямо на сайте?","a":"Занятия, как обычно, проходят в закрытом Telegram-канале или группе. Сайт отвечает за продажи и оплату, а бот — за доступ и подписку.","$h":{"q":"fu6eak","a":"1jp8g7t"}},"en":{"q":"Does the course run on the website itself?","a":"Lessons run as usual in a private Telegram channel or group. The website handles sales and payment, and the bot handles access and subscriptions.","$h":{"q":"fu6eak","a":"1jp8g7t"}}}'),
  '$.faq[1].i18n', json('{"ru":{"q":"Можно ли платить частями?","a":"Да, можно сделать месячную подписку или оплату в несколько частей — бот следит за сроком каждой части.","$h":{"q":"b0acqu","a":"isv6bs"}},"en":{"q":"Can students pay in installments?","a":"Yes, you can offer a monthly subscription or split payments — the bot tracks the due date of each installment.","$h":{"q":"b0acqu","a":"isv6bs"}}}'),
  '$.faq[2].i18n', json('{"ru":{"q":"Можно подключить мой существующий канал?","a":"Да, добавим бота администратором в ваш канал, список учеников сохранится.","$h":{"q":"sgkgi4","a":"177birz"}},"en":{"q":"Can it work with my existing channel?","a":"Yes, we add the bot to your channel as an admin, and your student list is kept.","$h":{"q":"sgkgi4","a":"177birz"}}}'))
