UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Бот голосовых заказов","summary":"Извлекает из голосового сообщения клиента товар, количество и адрес. После подтверждения клиентом заказ записывается в таблицу или CRM.","description":"Многим клиентам проще сказать, чем написать. Бот превращает голосовое сообщение в текст, выделяет из него товар, количество, адрес и время и собирает всё в аккуратную карточку. Клиент подтверждает одной кнопкой, а заказ попадает в таблицу или CRM. Понимает узбекскую, русскую и смешанную речь.","purpose":"Убрать время, которое уходит на прослушивание голосовых и ручную перепечатку.","features":["Голосовое сообщение превращается в текст — узбекская, русская и смешанная речь","Извлечение товара, количества, адреса и времени","Переспрашивает клиента, если что-то непонятно","Кнопки подтверждения и исправления для клиента","Запись в Google Sheets, amoCRM или Bitrix24","Менеджеру — текст вместе с исходным голосовым"],"platforms":["Telegram-бот","AI"],"problem":"Клиент присылает голосовое на минуту: «Здравствуйте, вот то, что вчера брали…». Менеджер слушает, переслушивает, потом записывает вручную. К концу дня набираются десятки голосовых — какие-то так и остаются непрослушанными.","customerView":["Голосовое сообщение — как обычно","Чёткая карточка понятого заказа","Кнопка подтверждения или исправления"],"ownerView":["Готовая карточка заказа — слушать не нужно","При необходимости — исходное голосовое","Новая строка в таблице или CRM"],"fit":["Доставка воды и газа","Магазины стройматериалов","Оптовая торговля","Ремонтные услуги","Аптеки","Небольшие производства"],"$h":{"name":"eztxhv","summary":"uf3t19","description":"rcyo6q","purpose":"m2x9ez","features":"tiiav3","platforms":"1b4w6f5","problem":"1j83i6j","customerView":"ivqaod","ownerView":"1wylnm","fit":"1hqtlvz"}},"en":{"name":"Voice order bot","summary":"Pulls the product, quantity and address out of a customer’s voice message. Once the customer confirms, the order is written to a spreadsheet or CRM.","description":"Many customers would rather talk than type. The bot turns a voice message into text, picks out the product, quantity, address and time, and puts them on a neat card. The customer confirms with one tap, and the order lands in a spreadsheet or CRM. It understands Uzbek, Russian and mixed speech.","purpose":"To eliminate the time spent listening to voice messages and retyping them by hand.","features":["Voice-to-text — Uzbek, Russian and mixed speech","Extracts product, quantity, address and time","Asks the customer again when something is unclear","Confirm and edit buttons for the customer","Writes to Google Sheets, amoCRM or Bitrix24","The manager gets the text along with the original voice message"],"platforms":["Telegram bot","AI"],"problem":"A customer sends a one-minute voice message: “Hi, that thing we got yesterday…”. The manager listens, listens again, then types it up by hand. By the end of the day dozens of voice messages pile up — some never get heard.","customerView":["Send a voice message as usual","A clear card of the understood order","A button to confirm or correct it"],"ownerView":["A ready order card — no listening needed","The original voice message if needed","A new row in the spreadsheet or CRM"],"fit":["Water and gas delivery","Building materials stores","Wholesale trade","Repair services","Pharmacies","Small manufacturers"],"$h":{"name":"eztxhv","summary":"uf3t19","description":"rcyo6q","purpose":"m2x9ez","features":"tiiav3","platforms":"1b4w6f5","problem":"1j83i6j","customerView":"ivqaod","ownerView":"1wylnm","fit":"1hqtlvz"}}}'),
  '$.demo.i18n', json('{"ru":{"bot":"Вода «Мусаффо»","$h":{"bot":"1rb9ixi"}},"en":{"bot":"Musaffo Water","$h":{"bot":"1rb9ixi"}}}'),
  '$.demo.nodes[0].i18n', json('{"ru":{"messages":["Вода «Мусаффо». Напишите заказ или отправьте голосовое сообщение."],"$h":{"messages":"1rix9zk"}},"en":{"messages":["Musaffo Water. Type your order or send a voice message."],"$h":{"messages":"1rix9zk"}}}'),
  '$.demo.nodes[0].buttons[0].i18n', json('{"ru":{"label":"Отправить голосовое · 0:18","$h":{"label":"19i5pbr"}},"en":{"label":"Send a voice message · 0:18","$h":{"label":"19i5pbr"}}}'),
  '$.demo.nodes[1].i18n', json('{"ru":{"messages":["Ваше голосовое сообщение:\n«Здравствуйте, привезите завтра утром две большие воды, пустые бутыли верну. Адрес тот же — Караташ 15, третий этаж.»","Я понял ваш заказ так:"],"$h":{"messages":"1eafkk4"}},"en":{"messages":["Your voice message:\n“Hi, please bring two big bottles of water tomorrow morning, I’ll return the empties. Same address — Qoratosh 15, third floor.”","Here’s how I understood your order:"],"$h":{"messages":"1eafkk4"}}}'),
