  '$.demo.nodes[2].buttons[0].i18n', json('{"ru":{"label":"Пусть будет 3 шт.","$h":{"label":"1n5v80d"}},"en":{"label":"Make it 3","$h":{"label":"1n5v80d"}}}'),
  '$.demo.nodes[2].buttons[1].i18n', json('{"ru":{"label":"Привезите вечером","$h":{"label":"12mw2yk"}},"en":{"label":"Bring it in the evening","$h":{"label":"12mw2yk"}}}'),
  '$.demo.nodes[3].i18n', json('{"ru":{"messages":["Принято! Курьер приедет завтра с 9:00 до 12:00."],"$h":{"messages":"1fnvjkj"}},"en":{"messages":["Got it! The courier will come tomorrow between 9:00 and 12:00."],"$h":{"messages":"1fnvjkj"}}}'),
  '$.demo.nodes[3].owner.i18n', json('{"ru":{"title":"Новый заказ (из голосового)","lines":["Караташ 15, 3-й этаж · завтра 9–12","Вода 19 л × 2 · тара возвращается","Записано в Google Sheets · исходное голосовое приложено"],"$h":{"title":"156l6j4","lines":"1dbt95p"}},"en":{"title":"New order (from voice)","lines":["Qoratosh 15, 3rd floor · tomorrow 9–12","Water 19 L × 2 · empties returned","Written to Google Sheets · original voice attached"],"$h":{"title":"156l6j4","lines":"1dbt95p"}}}'),
  '$.demo.nodes[4].i18n', json('{"ru":{"messages":["Обновлено: 3 шт., итого 54 000 сум. Курьер приедет завтра с 9:00 до 12:00."],"$h":{"messages":"1rel563"}},"en":{"messages":["Updated: 3 pcs, total 54,000 UZS. The courier will come tomorrow between 9:00 and 12:00."],"$h":{"messages":"1rel563"}}}'),
  '$.demo.nodes[4].owner.i18n', json('{"ru":{"title":"Новый заказ (из голосового)","lines":["Караташ 15, 3-й этаж · завтра 9–12","Вода 19 л × 3 · возврат 2 бутылей","Клиент сам исправил количество"],"$h":{"title":"156l6j4","lines":"1u6maux"}},"en":{"title":"New order (from voice)","lines":["Qoratosh 15, 3rd floor · tomorrow 9–12","Water 19 L × 3 · 2 empties returned","Customer corrected the quantity"],"$h":{"title":"156l6j4","lines":"1u6maux"}}}'),
  '$.demo.nodes[5].i18n', json('{"ru":{"messages":["Обновлено: завтра 17:00–20:00. Курьер приедет в это время."],"$h":{"messages":"cty0w5"}},"en":{"messages":["Updated: tomorrow 17:00–20:00. The courier will come in that window."],"$h":{"messages":"cty0w5"}}}'),
  '$.demo.nodes[5].owner.i18n', json('{"ru":{"title":"Новый заказ (из голосового)","lines":["Караташ 15, 3-й этаж · завтра 17–20","Вода 19 л × 2 · тара возвращается","Клиент сам исправил время"],"$h":{"title":"156l6j4","lines":"1x6ekf0"}},"en":{"title":"New order (from voice)","lines":["Qoratosh 15, 3rd floor · tomorrow 17–20","Water 19 L × 2 · empties returned","Customer corrected the time"],"$h":{"title":"156l6j4","lines":"1x6ekf0"}}}'),
  '$.steps[0].i18n', json('{"ru":{"title":"Голосовое","text":"Клиент, как обычно, наговаривает сообщение боту.","$h":{"title":"1rjy5bu","text":"2v9s8z"}},"en":{"title":"Voice message","text":"The customer simply records a message to the bot.","$h":{"title":"1rjy5bu","text":"2v9s8z"}}}'),
  '$.steps[1].i18n', json('{"ru":{"title":"Текст","text":"AI превращает голос в текст.","$h":{"title":"n56ufd","text":"187dttq"}},"en":{"title":"Text","text":"AI turns the voice into text.","$h":{"title":"n56ufd","text":"187dttq"}}}'),
  '$.steps[2].i18n', json('{"ru":{"title":"Разбор","text":"Из текста выделяются товар, количество, адрес и время.","$h":{"title":"1gxld7r","text":"1tcrkmk"}},"en":{"title":"Extraction","text":"The product, quantity, address and time are pulled from the text.","$h":{"title":"1gxld7r","text":"1tcrkmk"}}}'),
