  '$.steps[4].i18n', json('{"ru":{"title":"Запись","text":"Подтверждённый заказ попадает в таблицу или CRM, менеджеру приходит уведомление.","$h":{"title":"i5om63","text":"1v0bwid"}},"en":{"title":"Recording","text":"The confirmed order goes into the spreadsheet or CRM, and the manager is notified.","$h":{"title":"i5om63","text":"1v0bwid"}}}'),
  '$.beforeAfter[0].i18n', json('{"ru":{"before":"Каждое голосовое слушают и записывают вручную","after":"Заказ приходит готовой карточкой","$h":{"before":"14ihf61","after":"6mfqxb"}},"en":{"before":"Every voice message is played and typed up by hand","after":"The order arrives as a ready card","$h":{"before":"14ihf61","after":"6mfqxb"}}}'),
  '$.beforeAfter[1].i18n', json('{"ru":{"before":"Количество или адрес слышат неправильно","after":"Клиент видит карточку и сам подтверждает","$h":{"before":"k0y1o8","after":"1j98vis"}},"en":{"before":"Quantities or addresses are misheard","after":"The customer sees the card and confirms it","$h":{"before":"k0y1o8","after":"1j98vis"}}}'),
  '$.beforeAfter[2].i18n', json('{"ru":{"before":"Голосовые остаются непрослушанными","after":"Каждое — отдельная строка в таблице","$h":{"before":"1bkgowt","after":"3tdn2s"}},"en":{"before":"Voice messages go unheard","after":"Each one becomes its own row in the sheet","$h":{"before":"1bkgowt","after":"3tdn2s"}}}'),
  '$.faq[0].i18n', json('{"ru":{"q":"Понимает ли он диалект или смешанную речь?","a":"Хорошо понимает узбекскую, русскую и смешанную речь. Если что-то неясно, не угадывает, а уточняет у клиента.","$h":{"q":"zg50o1","a":"1b1h80g"}},"en":{"q":"Does it understand dialects or mixed speech?","a":"It handles Uzbek, Russian and mixed speech well. If something is unclear, it doesn’t guess — it asks the customer.","$h":{"q":"zg50o1","a":"1b1h80g"}}}'),
  '$.faq[1].i18n', json('{"ru":{"q":"Что если клиент не подтвердит карточку?","a":"Есть кнопка «Исправить»: клиент пишет или говорит, что изменить, и карточка обновляется.","$h":{"q":"16vn1ui","a":"f6p28j"}},"en":{"q":"What if the customer doesn’t confirm the card?","a":"There’s an “Edit” button: the customer types or says what to change, and the card updates.","$h":{"q":"16vn1ui","a":"f6p28j"}}}'),
  '$.faq[2].i18n', json('{"ru":{"q":"Сколько стоит AI?","a":"Расход на распознавание голоса и анализ считается отдельно, поминутно; примерные ежемесячные затраты назовём заранее.","$h":{"q":"1lr86sl","a":"1t7uuux"}},"en":{"q":"How much does the AI cost?","a":"Speech-to-text and analysis are billed separately, by the minute; we’ll tell you the estimated monthly cost upfront.","$h":{"q":"1lr86sl","a":"1t7uuux"}}}'))
