  AND json_array_length(data, '$.faq') = 3;

UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Sado","summary":"Программа для набора текста голосом. Удерживайте Alt и говорите: когда отпустите клавишу, Sado напишет сказанное там, где стоит курсор.","description":"Sado — программа для голосового набора в любом приложении Windows. Удерживаете Alt и говорите, а когда отпускаете — текст появляется там, где стоит курсор: дословно (Exact), в очищенном виде (Clean) или как готовое задание для AI-ассистента (Prompt). Понимает узбекский, русский и английский, даже смешанную речь.","purpose":"Записывать мысли быстрее, чем набирать их на клавиатуре, и легко давать AI-ассистентам чёткие, структурированные задания.","features":["Голосовой набор в любой программе по клавише Alt","Режимы Exact, Clean и Prompt","Узбекский, русский и английский языки","Бесплатный тариф: 30 минут в месяц","История хранится на компьютере в зашифрованном виде"],"platforms":["Windows 10 и 11","macOS — скоро"],"$h":{"name":"awo4bc","summary":"1hrtfp","description":"1f1nsf0","purpose":"qx8543","features":"oks5gu","platforms":"1xg5ya5"}},"en":{"name":"Sado","summary":"A voice typing app. Hold Alt and speak: when you release the key, Sado types what you said wherever your cursor is.","description":"Sado lets you type by voice in any Windows app. Hold Alt and speak, and when you let go, the text appears at your cursor: word for word (Exact), cleaned up (Clean) or as a ready-made task for an AI assistant (Prompt). It understands Uzbek, Russian and English, even mixed speech.","purpose":"To capture thoughts faster than typing and make it easy to give AI assistants clear, well-structured tasks.","features":["Voice typing in any app with the Alt key","Exact, Clean and Prompt modes","Uzbek, Russian and English","Free plan: 30 minutes a month","History is stored encrypted on your computer"],"platforms":["Windows 10 and 11","macOS — coming soon"],"$h":{"name":"awo4bc","summary":"1hrtfp","description":"1f1nsf0","purpose":"qx8543","features":"oks5gu","platforms":"1xg5ya5"}}}'))
WHERE slug = 'ovozdan-matnga';

UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Магазин в Telegram","summary":"Клиент выбирает товар прямо в Telegram, кладёт в корзину и оформляет заказ. Вы управляете заказами, оплатами и остатками.","description":"Создаём магазин для продаж прямо в Telegram. Клиент смотрит фото и цены, добавляет нужные товары в корзину, указывает адрес доставки и выбирает способ оплаты. Для добавления товаров, обновления цен и управления заказами у вас есть отдельная страница управления. О каждом новом заказе вы получаете уведомление в Telegram.","purpose":"Чтобы клиент сам выбирал товар и делал заказ, не тратя время на переписку о ценах.","features":["Каталог с категориями, фильтрами и поиском","Корзина, выбор доставки или самовывоза","Оплата через Payme, Click или наличными","Статус заказа: принят, собирается, в пути","Однократное напоминание о товаре в корзине","Предложение подходящего товара к корзине","Список «сообщите о поступлении» для закончившихся товаров","Изменение товаров, цен и остатков с телефона","Ежедневная сводка продаж в Telegram"],"platforms":["Telegram Mini App","Telegram-бот"],"problem":"Товары — в Instagram, вопросы — в директе, заказы — в тетради. Каждому клиенту приходится отдельно расписывать цену, размер и доставку. Вопрос, пришедший ночью, остаётся без ответа до утра, и клиент покупает в другом месте.","customerView":["Каталог с фото, ценами и размерами","Заказ и оплата в несколько нажатий","Уведомления о статусе заказа","История прошлых заказов"],"ownerView":["Каждый новый заказ — с составом, суммой и адресом","Оплачен заказ или нет","Сводка продаж за день и месяц","Список заканчивающихся товаров"],"fit":["Одежда и обувь","Косметика","Цветы и подарки","Аксессуары для телефонов","Товары для дома","Изделия ручной работы"],"$h":{"name":"1jr7nvv","summary":"1doe3p","description":"1qpf171","purpose":"1qvcbhd","features":"byh5yw","platforms":"1byvv3s","problem":"1t6yuyn","customerView":"5t799f","ownerView":"b810qb","fit":"zka0n9"}},"en":{"name":"Telegram shop","summary":"Customers pick products inside Telegram, add them to a cart and place an order. You manage orders, payments and stock.","description":"We build a shop for selling right inside Telegram. Customers browse photos and prices, add items to the cart, enter a delivery address and choose how to pay. You get a separate management page to add products, update prices and handle orders, plus a Telegram alert for every new order.","purpose":"So customers pick products and order on their own, without messaging back and forth about prices.","features":["Catalog with categories, filters and search","Cart with delivery or pickup","Payment via Payme, Click or cash","Order status: received, being packed, on the way","One-time reminder about items left in the cart","Suggestions of matching items for the cart","“Notify me when it’s back” list for sold-out items","Edit products, prices and stock from your phone","Daily sales summary in Telegram"],"platforms":["Telegram Mini App","Telegram bot"],"problem":"Products live on Instagram, questions in DMs, orders in a notebook. Every customer needs a separate explanation of price, size and delivery. A question that arrives at night waits until morning, and the customer buys elsewhere.","customerView":["A catalog with photos, prices and sizes","Order and pay in a few taps","Order status updates","History of past orders"],"ownerView":["Every new order with items, total and address","Whether it’s paid or not","Daily and monthly sales summaries","A list of products running low"],"fit":["Clothing and shoes","Cosmetics","Flowers and gifts","Phone accessories","Household goods","Handmade products"],"$h":{"name":"1jr7nvv","summary":"1doe3p","description":"1qpf171","purpose":"1qvcbhd","features":"byh5yw","platforms":"1byvv3s","problem":"1t6yuyn","customerView":"5t799f","ownerView":"b810qb","fit":"zka0n9"}}}'),
  '$.demo.i18n', json('{"ru":{"bot":"Бутик «Нафис»","$h":{"bot":"1sg6rfd"}},"en":{"bot":"Nafis Boutique","$h":{"bot":"1sg6rfd"}}}'),
