  '$.steps[0].i18n', json('{"ru":{"title":"Каталог","text":"Загружаем товары, цены, фото и остатки — можно перенести из Excel.","$h":{"title":"1nbvlsg","text":"qj6zga"}},"en":{"title":"Catalog","text":"We upload products, prices, photos and stock — importing from Excel works too.","$h":{"title":"1nbvlsg","text":"qj6zga"}}}'),
  '$.steps[1].i18n', json('{"ru":{"title":"Клиент выбирает","text":"Открывает магазин кнопкой в боте, ищет с фильтрами, добавляет в корзину.","$h":{"title":"10d84ua","text":"jjz8aq"}},"en":{"title":"The customer chooses","text":"They open the shop from the bot button, search with filters and add to the cart.","$h":{"title":"10d84ua","text":"jjz8aq"}}}'),
  '$.steps[2].i18n', json('{"ru":{"title":"Оплата","text":"Платит через Payme или Click либо выбирает оплату наличными.","$h":{"title":"1670rih","text":"sn85l8"}},"en":{"title":"Payment","text":"They pay via Payme or Click, or choose cash.","$h":{"title":"1670rih","text":"sn85l8"}}}'),
  '$.steps[3].i18n', json('{"ru":{"title":"Уведомление вам","text":"Заказ приходит в Telegram с составом, адресом и статусом оплаты.","$h":{"title":"1sjk88d","text":"1yci8v5"}},"en":{"title":"You get notified","text":"The order arrives in Telegram with items, address and payment status.","$h":{"title":"1sjk88d","text":"1yci8v5"}}}'),
  '$.steps[4].i18n', json('{"ru":{"title":"Статус","text":"Меняете статус одной кнопкой, клиенту автоматически приходит сообщение.","$h":{"title":"1wiix2x","text":"immrnm"}},"en":{"title":"Status","text":"You change the status with one tap, and the customer is notified automatically.","$h":{"title":"1wiix2x","text":"immrnm"}}}'),
  '$.steps[5].i18n', json('{"ru":{"title":"Напоминание о незавершённом заказе","text":"Клиенту, бросившему корзину, позже приходит одно вежливое напоминание.","$h":{"title":"cb37n3","text":"1wxv9gs"}},"en":{"title":"Abandoned order reminder","text":"A customer who left their cart gets one polite reminder later.","$h":{"title":"cb37n3","text":"1wxv9gs"}}}'),
  '$.beforeAfter[0].i18n', json('{"ru":{"before":"Каждому клиенту пишете цену в директ","after":"Клиент сам видит цену в каталоге","$h":{"before":"1qo2pii","after":"cl0y9u"}},"en":{"before":"You message each customer the price in DMs","after":"Customers see the price in the catalog themselves","$h":{"before":"1qo2pii","after":"cl0y9u"}}}'),
  '$.beforeAfter[1].i18n', json('{"ru":{"before":"Заказ записывается в тетрадь","after":"Заказ сохраняется автоматически — с составом и адресом","$h":{"before":"1emymm9","after":"d301gx"}},"en":{"before":"Orders are written in a notebook","after":"Orders are saved automatically with items and address","$h":{"before":"1emymm9","after":"d301gx"}}}'),
  '$.beforeAfter[2].i18n', json('{"ru":{"before":"Оплату проверяют по фото чека","after":"Оплата через Payme или Click подтверждается сама","$h":{"before":"11e2vdz","after":"5ov6mn"}},"en":{"before":"Payments are checked from receipt photos","after":"Payme or Click payments confirm themselves","$h":{"before":"11e2vdz","after":"5ov6mn"}}}'),
  '$.beforeAfter[3].i18n', json('{"ru":{"before":"О клиенте, бросившем корзину, забывают","after":"Ему вовремя приходит напоминание","$h":{"before":"y4m9us","after":"1c9msin"}},"en":{"before":"Customers who abandon carts are forgotten","after":"They get a timely reminder","$h":{"before":"y4m9us","after":"1c9msin"}}}'),
  '$.faq[0].i18n', json('{"ru":{"q":"Чем Mini App отличается от обычного бота?","a":"В обычном боте товар выбирают кнопками и сообщениями. Mini App — это полноценная страница внутри Telegram: каталог с фото, фильтры и корзина. Если товаров много, Mini App удобнее.","$h":{"q":"hfwv6u","a":"1ke1gn"}},"en":{"q":"How is a Mini App different from a regular bot?","a":"In a regular bot, products are chosen with buttons and messages. A Mini App is a full page inside Telegram with a photo catalog, filters and a cart. With many products, a Mini App is more convenient.","$h":{"q":"hfwv6u","a":"1ke1gn"}}}'),
  '$.faq[1].i18n', json('{"ru":{"q":"Что нужно для подключения Payme или Click?","a":"Нужен счёт продавца (мерчант) в платёжной системе. Поможем его открыть, сначала проверим в тестовом режиме, а затем подключим боевой.","$h":{"q":"1h327tb","a":"fbxva9"}},"en":{"q":"What do I need to connect Payme or Click?","a":"You need a merchant account with the payment provider. We’ll help you open one, test everything in sandbox mode and then go live.","$h":{"q":"1h327tb","a":"fbxva9"}}}'),
  '$.faq[2].i18n', json('{"ru":{"q":"Смогу ли я сам добавлять товары?","a":"Да, через админ-панель или команды администратора в боте вы меняете товары, цены и остатки прямо с телефона.","$h":{"q":"1kj4wq","a":"15ved3n"}},"en":{"q":"Can I add products myself?","a":"Yes, through the admin panel or the bot’s admin commands you can change products, prices and stock from your phone.","$h":{"q":"1kj4wq","a":"15ved3n"}}}'))
