  AND json_array_length(data, '$.faq') = 3;

UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Бот для записи на приём","summary":"Клиент выбирает услугу, специалиста и удобное время. Бот напоминает о визите, а вы видите расписание приёма.","description":"Бот записи на приём для салона, клиники или учебного центра. Клиент видит только свободное время, записывается в несколько нажатий, переносит или отменяет запись. Перед визитом бот напоминает. Вы и специалисты видите расписание на день в Telegram или в Google Sheets.","purpose":"Меньше записей по телефону, двойных записей на одно время и неявок.","features":["Выбор услуги, специалиста и свободного времени","Показывается только действительно свободное время","Перенос или отмена записи одной кнопкой","Напоминание за день и за 2 часа до визита","У каждого специалиста — своё расписание на день","Связь с Google Sheets","Запрос оценки после визита"],"platforms":["Telegram-бот","Google Sheets"],"problem":"Администратор весь день на телефоне: кто когда придёт, какой мастер свободен. Иногда двое клиентов записываются на одно время, а кто-то не приходит, и время пропадает.","customerView":["Список свободного времени","Подтверждение записи и адрес","Напоминание перед визитом","Кнопки переноса и отмены"],"ownerView":["Уведомление о каждой новой записи","Расписание на день по специалистам","Отменённые и перенесённые записи","Полный список в Google Sheets"],"fit":["Салоны красоты","Барбершопы","Стоматологии и клиники","Репетиторы","Автосервисы","Психологи и консультанты"],"$h":{"name":"1tvxfud","summary":"cdmy41","description":"scewk1","purpose":"1gte1ze","features":"147k785","platforms":"dxqxp2","problem":"weho89","customerView":"14aieza","ownerView":"zqba7b","fit":"1vnxjv"}},"en":{"name":"Appointment booking bot","summary":"Customers choose a service, a specialist and a convenient time. The bot sends reminders, and you see the schedule.","description":"An appointment booking bot for a salon, clinic or training center. Customers see only open slots, book in a few taps, and can reschedule or cancel. The bot sends a reminder before the visit. You and your specialists see the day’s schedule in Telegram or Google Sheets.","purpose":"Fewer phone bookings, no double-booked slots and fewer no-shows.","features":["Choice of service, specialist and open slot","Only truly free slots are shown","Reschedule or cancel with one tap","Reminders a day and 2 hours before the visit","Each specialist gets their own daily schedule","Google Sheets integration","Feedback request after the visit"],"platforms":["Telegram bot","Google Sheets"],"problem":"The receptionist spends the whole day on the phone: who’s coming when, which stylist is free. Sometimes two customers book the same slot, while others don’t show up and the time goes to waste.","customerView":["A list of open slots","Booking confirmation and address","A reminder before the visit","Reschedule and cancel buttons"],"ownerView":["A notification for every new booking","Daily schedule by specialist","Cancelled and rescheduled bookings","A full list in Google Sheets"],"fit":["Beauty salons","Barbershops","Dental offices and clinics","Tutors","Car service centers","Psychologists and consultants"],"$h":{"name":"1tvxfud","summary":"cdmy41","description":"scewk1","purpose":"1gte1ze","features":"147k785","platforms":"dxqxp2","problem":"weho89","customerView":"14aieza","ownerView":"zqba7b","fit":"1vnxjv"}}}'),
