  '$.demo.nodes[6].i18n', json('{"ru":{"messages":["За 2 часа до визита приходит такое сообщение:","Сегодня в 15:30 вы записаны на маникюр. Придёте?"],"$h":{"messages":"rb4ouq"}},"en":{"messages":["Two hours before the visit, you get a message like this:","You’re booked for a manicure today at 15:30. Are you coming?"],"$h":{"messages":"rb4ouq"}}}'),
