  '$.steps[0].i18n', json('{"ru":{"title":"Расписание","text":"Вносим услуги, их длительность, специалистов и часы работы.","$h":{"title":"1ezybbz","text":"z77u8x"}},"en":{"title":"Schedule","text":"We enter services, their duration, specialists and working hours.","$h":{"title":"1ezybbz","text":"z77u8x"}}}'),
  '$.steps[1].i18n', json('{"ru":{"title":"Клиент выбирает","text":"Бот показывает только свободное время, клиент выбирает удобное.","$h":{"title":"10d84ua","text":"1o8ywn4"}},"en":{"title":"The customer chooses","text":"The bot shows only open slots, and the customer taps the one that suits them.","$h":{"title":"10d84ua","text":"1o8ywn4"}}}'),
  '$.steps[2].i18n', json('{"ru":{"title":"Подтверждение","text":"Клиент получает подтверждение записи, специалист — новую запись.","$h":{"title":"1i2cbx7","text":"1tnxpne"}},"en":{"title":"Confirmation","text":"The customer gets a booking confirmation, and the specialist gets the new entry.","$h":{"title":"1i2cbx7","text":"1tnxpne"}}}'),
