UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"AI-ассистент для клиентов","summary":"Отвечает на вопросы о ваших услугах и ценах. Записывает обращение и при необходимости передаёт его сотруднику.","description":"Ассистент отвечает на основе ваших цен, услуг и правил. Работает в Telegram или в окне чата на вашем сайте. Когда клиент называет, что ему нужно, свой бюджет и сроки, ассистент передаёт менеджеру заявку в виде аккуратной карточки. Если для ответа не хватает данных, вопрос уходит сотруднику.","purpose":"Чтобы клиент не ушёл к другим, не дождавшись ответа, а менеджер не отвечал весь день на одни и те же вопросы.","features":["Ответы о ценах, услугах, адресе и часах работы — из вашей базы знаний","На узбекском (латиница и кириллица) и русском","Выясняет, что нужно клиенту: потребность, бюджет, сроки","Передаёт сотруднику имя клиента, запрос и контакты","Переводит сложный или неясный вопрос на сотрудника","Ответы редактируются в админ-панели","История диалогов и самые частые вопросы"],"platforms":["Telegram-бот","Чат на сайте"],"problem":"Клиент пишет в 11 вечера и спрашивает цену. Пока менеджер ответит утром, он уже закажет у других. А днём большая часть времени менеджера уходит на одни и те же вопросы: «сколько стоит?», «где вы находитесь?».","customerView":["Мгновенный и точный ответ на вопрос","Понятное объяснение цен и услуг","При необходимости — связь с живым сотрудником","Подтверждение, что заявка принята"],"ownerView":["Каждая новая заявка — с именем, потребностью, бюджетом и сроками","Вопросы, на которые ассистент не ответил, — отдельно","История всех диалогов","Список самых частых вопросов"],"fit":["Учебные центры","Клиники","Агентства недвижимости","Ремонт и строительство","Интернет-магазины","Турфирмы"],"$h":{"name":"1g2buya","summary":"1bwwqtf","description":"moa4sa","purpose":"148u1h5","features":"njt0xg","platforms":"34e3q1","problem":"7wdn2o","customerView":"1d9ydbt","ownerView":"dz491n","fit":"c9wgsa"}},"en":{"name":"AI assistant for customers","summary":"Answers questions about your services and prices. It records each request and forwards it to a staff member when needed.","description":"The assistant answers based on your prices, services and policies. It works on Telegram or in a chat window on your website. Once a customer says what they need, their budget and timeline, the assistant hands the manager a neat lead card. If there isn’t enough information to answer, the question goes to a staff member.","purpose":"So customers don’t leave while waiting for an answer, and managers don’t spend all day answering the same questions.","features":["Answers on prices, services, address and opening hours — from your own knowledge base","In Uzbek (Latin and Cyrillic) and Russian","Finds out what the customer needs: requirements, budget, timeline","Sends the customer’s name, request and contact details to your staff","Passes complex or unclear questions to a staff member","Edit answers in the admin panel","Conversation history and the most frequent questions"],"platforms":["Telegram bot","Website chat"],"problem":"A customer messages at 11 p.m. asking for a price. By the time the manager replies in the morning, they’ve already ordered elsewhere. During the day, much of the manager’s time goes to the same questions: “how much is it?”, “where are you located?”.","customerView":["An instant, accurate answer","A clear explanation of prices and services","A live staff member when needed","Confirmation that the request was received"],"ownerView":["Every new lead with name, needs, budget and timeline","Questions the assistant couldn’t answer, listed separately","History of all conversations","A list of the most frequent questions"],"fit":["Training centers","Clinics","Real estate agencies","Renovation and construction","Online stores","Travel agencies"],"$h":{"name":"1g2buya","summary":"1bwwqtf","description":"moa4sa","purpose":"148u1h5","features":"njt0xg","platforms":"34e3q1","problem":"7wdn2o","customerView":"1d9ydbt","ownerView":"dz491n","fit":"c9wgsa"}}}'),
