  '$.steps[0].i18n', json('{"ru":{"title":"Собираем знания","text":"Сводим ваши цены, услуги, вопросы-ответы и правила в одну базу.","$h":{"title":"17atsrq","text":"qk6yoc"}},"en":{"title":"We gather knowledge","text":"We put your prices, services, FAQs and policies into one knowledge base.","$h":{"title":"17atsrq","text":"qk6yoc"}}}'),
  '$.steps[1].i18n', json('{"ru":{"title":"Настраиваем тон","text":"Определяем, как ассистент обращается к клиенту, чего он не обещает и когда зовёт сотрудника.","$h":{"title":"16exmkl","text":"t17hf6"}},"en":{"title":"We set the tone","text":"We decide how the assistant addresses customers, what it never promises and when it calls a staff member.","$h":{"title":"16exmkl","text":"t17hf6"}}}'),
  '$.steps[2].i18n', json('{"ru":{"title":"Клиент пишет","text":"Задаёт вопрос в Telegram или на сайте, ассистент отвечает мгновенно.","$h":{"title":"8uwuaw","text":"1xdleni"}},"en":{"title":"The customer writes","text":"They ask a question on Telegram or the website, and the assistant replies instantly.","$h":{"title":"8uwuaw","text":"1xdleni"}}}'),
  '$.steps[3].i18n', json('{"ru":{"title":"Уточняет","text":"Спрашивает нужную услугу, бюджет и сроки и заполняет заявку.","$h":{"title":"1vpphcx","text":"1oikpmw"}},"en":{"title":"It qualifies","text":"It asks about the service, budget and timeline and fills in the lead.","$h":{"title":"1vpphcx","text":"1oikpmw"}}}'),
  '$.steps[4].i18n', json('{"ru":{"title":"Передаёт","text":"Готовая заявка или вопрос без ответа приходит менеджеру в Telegram.","$h":{"title":"1vy722d","text":"1vnou1g"}},"en":{"title":"It hands off","text":"The finished lead or an unanswered question reaches the manager on Telegram.","$h":{"title":"1vy722d","text":"1vnou1g"}}}'),
  '$.steps[5].i18n', json('{"ru":{"title":"Донастраиваем","text":"В первый месяц просматриваем диалоги и уточняем ответы.","$h":{"title":"csng2c","text":"1qxk4li"}},"en":{"title":"We fine-tune","text":"During the first month we review conversations and refine the answers.","$h":{"title":"csng2c","text":"1qxk4li"}}}'),
  '$.beforeAfter[0].i18n', json('{"ru":{"before":"Клиент, написавший ночью, ждёт ответа до утра","after":"Ответ за несколько секунд, даже ночью","$h":{"before":"jg9eg7","after":"mhhr1h"}},"en":{"before":"A customer who writes at night waits until morning","after":"An answer in seconds, even at night","$h":{"before":"jg9eg7","after":"mhhr1h"}}}'),
  '$.beforeAfter[1].i18n', json('{"ru":{"before":"Менеджер снова и снова отвечает на одни и те же вопросы","after":"Менеджеру приходят только готовые заявки и сложные вопросы","$h":{"before":"doufcf","after":"henstc"}},"en":{"before":"The manager answers the same questions over and over","after":"The manager gets only finished leads and complex questions","$h":{"before":"doufcf","after":"henstc"}}}'),
  '$.beforeAfter[2].i18n', json('{"ru":{"before":"Заявки теряются между чатами","after":"Каждая заявка — в одной аккуратной карточке","$h":{"before":"1jsd3vh","after":"1bz4buj"}},"en":{"before":"Leads get lost between chats","after":"Every lead lives in one neat card","$h":{"before":"1jsd3vh","after":"1bz4buj"}}}'),
  '$.beforeAfter[3].i18n', json('{"ru":{"before":"Бюджет и сроки выясняются потом","after":"Они уже указаны в самой заявке","$h":{"before":"1jog2qw","after":"zxdow7"}},"en":{"before":"Budget and timeline are figured out later","after":"They’re already in the lead itself","$h":{"before":"1jog2qw","after":"zxdow7"}}}'),
  '$.faq[0].i18n', json('{"ru":{"q":"Не ответит ли ассистент неправильно?","a":"Он отвечает только на основе данных, которые дали вы. Если информации для ответа не хватает, он сообщает клиенту, что с ним свяжется сотрудник, и передаёт вопрос вам.","$h":{"q":"2splbb","a":"s9e9q3"}},"en":{"q":"Won’t the assistant give wrong answers?","a":"It answers only from the information you provide. If there isn’t enough to answer, it tells the customer a staff member will get in touch and forwards the question to you.","$h":{"q":"2splbb","a":"s9e9q3"}}}'),
  '$.faq[1].i18n', json('{"ru":{"q":"Нужно ли отдельно платить за AI-сервис?","a":"Да, расход AI-сервиса (токены) оплачивается отдельно. Мы заранее рассчитаем ежемесячные затраты исходя из количества диалогов.","$h":{"q":"1u0fvou","a":"1qvk31d"}},"en":{"q":"Is there a separate fee for the AI service?","a":"Yes, AI service usage (tokens) is billed separately. We estimate the monthly cost upfront based on the number of conversations.","$h":{"q":"1u0fvou","a":"1qvk31d"}}}'),
  '$.faq[2].i18n', json('{"ru":{"q":"Что если мои цены изменятся?","a":"Вы сами обновляете их в админ-панели — ассистент сразу начинает отвечать с новыми данными.","$h":{"q":"13mbx8l","a":"7zrl40"}},"en":{"q":"What if my prices change?","a":"You update them yourself in the admin panel, and the assistant starts using the new information right away.","$h":{"q":"13mbx8l","a":"7zrl40"}}}'))
