UPDATE projects SET data = json_set(data,
  '$.i18n', json('{"ru":{"name":"Все заявки в одном месте","summary":"Заявки с сайта, из Telegram и Instagram попадают в один список. Каждой назначается ответственный, о неотвеченных приходит напоминание.","description":"Откуда бы ни пришла заявка — форма сайта, директ Instagram, Telegram-бот или рекламная форма — система собирает всё в один список. Каждая заявка записывается с источником, назначается следующему по очереди менеджеру, и ему приходит уведомление в Telegram. О заявке без ответа система напоминает, а в конце месяца видно, какой источник привёл больше клиентов.","purpose":"Чтобы ни одна заявка не потерялась и было понятно, куда уходят деньги на рекламу.","features":["Сбор из формы сайта, Instagram, Telegram и рекламных форм","Запись в Google Sheets, amoCRM или Bitrix24","Распределение по менеджерам по очереди","Мгновенное уведомление менеджеру в Telegram","Напоминание о заявке без ответа и уведомление руководителю","Объединение повторных заявок одного клиента","Ежемесячный отчёт по источникам"],"platforms":["Интеграция","Telegram-бот","Google Sheets / CRM"],"problem":"Заявки приходят в пять мест: форма сайта — на почту, Instagram — в директ, Telegram — в личный чат. Менеджеры проверяют каждое отдельно: какие-то заявки видят с опозданием на день, какие-то не видят вовсе. А какая реклама работает, не знает никто.","customerView":["Быстрый ответ, в каком бы канале клиент ни написал","Не нужно задавать один и тот же вопрос дважды"],"ownerView":["Все заявки в одном списке","Источник и ответственный менеджер у каждой заявки","Заявки без ответа","Ежемесячный отчёт по источникам"],"fit":["Недвижимость","Учебные центры","Клиники","Ремонт и строительство","Автосалоны","Любой бизнес, который даёт рекламу"],"$h":{"name":"ezx8g2","summary":"10119ft","description":"mqwpno","purpose":"wlhzyl","features":"19hvmgt","platforms":"1yjp3zd","problem":"9ku57k","customerView":"1t5noks","ownerView":"ky6sjj","fit":"swfasp"}},"en":{"name":"All leads in one place","summary":"Leads from your website, Telegram and Instagram land in a single list. Each gets an owner, and you’re reminded about unanswered ones.","description":"Wherever a lead comes from — a website form, an Instagram DM, a Telegram bot or an ad form — the system collects them all into one list. Each lead is recorded with its source, assigned to the next manager in line, and that manager gets a Telegram alert. The system reminds you about unanswered leads, and at the end of the month you see which source brought the most customers.","purpose":"So no lead gets lost and you know where your ad budget is going.","features":["Collects from website forms, Instagram, Telegram and ad forms","Writes to Google Sheets, amoCRM or Bitrix24","Round-robin assignment to managers","Instant Telegram alert to the manager","Reminders about unanswered leads, with escalation to the owner","Merges duplicate leads from the same customer","Monthly report by source"],"platforms":["Integration","Telegram bot","Google Sheets / CRM"],"problem":"Leads arrive in five places: website forms go to email, Instagram to DMs, Telegram to a personal chat. Managers check each one separately — some leads are seen a day late, some never. And nobody knows which ads actually work.","customerView":["A quick reply, whichever channel they use","No need to ask the same question twice"],"ownerView":["All leads in one list","Each lead’s source and responsible manager","Unanswered leads","Monthly report by source"],"fit":["Real estate","Training centers","Clinics","Renovation and construction","Car dealerships","Any business that runs ads"],"$h":{"name":"ezx8g2","summary":"10119ft","description":"mqwpno","purpose":"wlhzyl","features":"19hvmgt","platforms":"1yjp3zd","problem":"9ku57k","customerView":"1t5noks","ownerView":"ky6sjj","fit":"swfasp"}}}'),
